﻿@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="da">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no, maximum-scale=1.0">
    <title>Jeopardy - Vært</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Arial', sans-serif;
            background: linear-gradient(135deg, #1e3c72, #2a5298);
            color: white;
            min-height: 100vh;
            padding: 20px;
            touch-action: manipulation;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
        }

        .host-header {
            text-align: center;
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 15px;
            margin-bottom: 20px;
            backdrop-filter: blur(10px);
        }

        .game-code {
            font-size: 2.5em;
            color: #FFD700;
            font-weight: bold;
            background: rgba(0, 0, 0, 0.3);
            padding: 15px;
            border-radius: 10px;
            margin: 10px 0;
        }

        .players-section {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 15px;
            margin-bottom: 20px;
            backdrop-filter: blur(10px);
        }

        .players-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 15px;
            margin-top: 15px;
        }

        .player-card {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            text-align: center;
        }

        .player-score {
            font-size: 1.5em;
            color: #FFD700;
            font-weight: bold;
        }

        .game-board {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 10px;
            margin: 20px 0;
        }

        .category-header {
            background: #FFD700;
            color: #000;
            padding: 20px;
            text-align: center;
            font-weight: bold;
            font-size: 1.1em;
            border-radius: 8px;
            text-transform: uppercase;
        }

        .question-tile {
            background: #000080;
            color: #FFD700;
            padding: 30px;
            text-align: center;
            font-size: 1.8em;
            font-weight: bold;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.3s ease;
            border: 3px solid #FFD700;
        }

            .question-tile:hover {
                background: #0000CD;
                transform: scale(1.05);
            }

            .question-tile.used {
                background: #333;
                color: #666;
                cursor: not-allowed;
                opacity: 0.5;
            }

        .buzz-panel {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 15px;
            margin-top: 20px;
            backdrop-filter: blur(10px);
        }

        .timer-display {
            background: #ff6b6b;
            color: white;
            padding: 10px 20px;
            border-radius: 50px;
            font-size: 1.5em;
            font-weight: bold;
            margin: 10px 0;
            text-align: center;
            transition: background-color 0.3s ease;
        }

            .timer-display.expired {
                background: #666;
            }

            .timer-display.extended {
                background: #ff9500;
            }

        .progress-container {
            width: 100%;
            height: 20px;
            background: rgba(255, 255, 255, 0.2);
            border-radius: 10px;
            margin: 10px 0;
            overflow: hidden;
            position: relative;
            display: none;
        }

        .progress-bar {
            height: 100%;
            background: linear-gradient(45deg, #4CAF50, #8BC34A);
            width: 0%;
            border-radius: 10px;
            transition: width 1s linear;
            position: relative;
            overflow: hidden;
        }

        .progress-bar::after {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
            animation: shimmer 2s infinite;
        }

        .progress-text {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            font-size: 0.9em;
            font-weight: bold;
            color: white;
            text-shadow: 1px 1px 2px rgba(0,0,0,0.5);
            z-index: 1;
        }

        @@keyframes shimmer {
            0% { transform: translateX(-100%); }
            100% { transform: translateX(100%); }
        }

        .buzz-list {
            margin: 15px 0;
        }

        .buzz-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 8px;
            margin: 5px 0;
        }

        .buzz-order {
            background: #FFD700;
            color: #000;
            padding: 8px 12px;
            border-radius: 50%;
            font-weight: bold;
        }

        .btn {
            background: linear-gradient(45deg, #667eea, #764ba2);
            border: none;
            color: white;
            padding: 12px 25px;
            font-size: 1em;
            border-radius: 8px;
            cursor: pointer;
            margin: 5px;
            transition: all 0.3s ease;
        }

            .btn:hover {
                transform: translateY(-2px);
                box-shadow: 0 8px 15px rgba(0, 0, 0, 0.3);
            }

        .btn-danger {
            background: linear-gradient(45deg, #ff6b6b, #ee5a24);
        }

        .score-controls {
            display: flex;
            gap: 10px;
            margin-top: 10px;
        }

        .score-input {
            width: 80px;
            padding: 5px;
            border-radius: 4px;
            border: none;
            text-align: center;
        }

        .hidden {
            display: none;
        }

        /* Team Mode Styles */
        .team-lobby {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 15px;
            margin-bottom: 20px;
            backdrop-filter: blur(10px);
        }

        .team-creation {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            margin-bottom: 20px;
        }

        .team-input-group {
            display: flex;
            gap: 10px;
            margin: 10px 0;
            flex-wrap: wrap;
        }

        .team-input-group input {
            flex: 1;
            min-width: 150px;
            padding: 10px;
            border-radius: 8px;
            border: none;
            font-size: 1em;
        }

        .teams-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 15px;
            margin-top: 15px;
        }

        .team-card {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            border-left: 5px solid;
        }

        .team-members {
            margin-top: 10px;
            font-size: 0.9em;
        }

        .team-member {
            background: rgba(255, 255, 255, 0.1);
            padding: 5px 10px;
            border-radius: 5px;
            margin: 5px 0;
        }

        .waiting-players {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            margin-top: 15px;
        }

        .waiting-player {
            background: rgba(255, 255, 255, 0.1);
            padding: 8px 12px;
            border-radius: 5px;
            margin: 5px 0;
            display: inline-block;
            margin-right: 10px;
        }

        @@media (max-width: 768px) {
            body {
                padding: 10px;
            }

            .game-board {
                grid-template-columns: repeat(2, 1fr);
                gap: 6px;
            }

            .question-tile {
                padding: 15px 8px;
                font-size: 1.2em;
                min-height: 50px;
            }

            .category-header {
                padding: 8px 4px;
                font-size: 0.8em;
            }

            .players-grid {
                grid-template-columns: 1fr;
            }

            .game-code {
                font-size: 2em;
                padding: 10px;
            }

            .host-header, .players-section, .buzz-panel {
                padding: 15px;
                margin-bottom: 15px;
            }

            .player-card {
                padding: 10px;
            }

            .btn {
                padding: 10px 20px;
                font-size: 0.9em;
                margin: 3px;
            }

            .buzz-item {
                padding: 10px;
                font-size: 0.9em;
            }

            .score-controls {
                flex-direction: column;
                gap: 5px;
            }

            .score-input {
                width: 100%;
                margin-bottom: 5px;
            }
        }

        @@media (max-width: 480px) {
            body {
                padding: 5px;
            }

            .container {
                max-width: 100%;
            }

            .game-board {
                grid-template-columns: repeat(2, 1fr);
                gap: 4px;
            }

            .question-tile {
                padding: 10px 6px;
                font-size: 1em;
                min-height: 45px;
            }

            .category-header {
                padding: 6px 2px;
                font-size: 0.7em;
            }

            .game-code {
                font-size: 1.6em;
                padding: 8px;
            }

            .host-header h1 {
                font-size: 1.5em;
            }

            .players-section h2 {
                font-size: 1.2em;
            }

            .buzz-panel h2 {
                font-size: 1.2em;
            }

            .timer-display {
                font-size: 1.2em;
                padding: 8px 15px;
            }

            .btn {
                padding: 8px 15px;
                font-size: 0.8em;
                margin: 2px;
            }

            .buzz-item {
                padding: 8px;
                font-size: 0.8em;
            }

            .buzz-order {
                padding: 6px 10px;
            }

            .player-score {
                font-size: 1.2em;
            }
        }

        @@media (max-width: 896px) and (orientation: landscape) {
            .game-board {
                grid-template-columns: repeat(5, 1fr);
                gap: 3px;
            }

            .question-tile {
                padding: 8px 4px;
                font-size: 0.9em;
                min-height: 40px;
            }

            .category-header {
                padding: 4px 2px;
                font-size: 0.6em;
            }

            .players-grid {
                grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="host-header">
            <h1> Jeopardy Vært</h1>
            <div class="game-code">Spil Kode: <span id="gameCodeDisplay">----</span></div>
            <button class="btn btn-danger" onclick="endGame()">Afslut Spil</button>
        </div>

        <!-- Team Lobby (shown only in team mode before game starts) -->
        <div id="teamLobby" class="team-lobby hidden">
            <h2>Hold Opsætning</h2>
            <div class="team-creation">
                <h3>Opret Hold</h3>
                <div class="team-input-group">
                    <input type="text" id="teamName" placeholder="Hold navn" maxlength="30">
                    <input type="color" id="teamColor" value="#667eea">
                    <button class="btn" onclick="createTeam()">Opret Hold</button>
                </div>
            </div>
            <div id="teamsGrid" class="teams-grid"></div>
            <div class="waiting-players">
                <h3>Ventende Spillere</h3>
                <div id="waitingPlayers">Ingen spillere venter endnu...</div>
            </div>
            <button class="btn" onclick="startGame()" style="background: linear-gradient(45deg, #4CAF50, #8BC34A); width: 100%; margin-top: 20px; font-size: 1.2em;">Start Spil</button>
        </div>

        <div class="players-section" id="playersSection">
            <h2>Spillere (<span id="playerCount">0</span>)</h2>
            <div id="playersGrid" class="players-grid"></div>
        </div>

        <div id="gameBoard" class="game-board"></div>

        <div id="buzzPanel" class="buzz-panel hidden">
            <h2>Spillere der buzzede:</h2>
            <div id="timerDisplay" class="timer-display">10</div>
            <div id="progressContainer" class="progress-container">
                <div id="progressBar" class="progress-bar"></div>
                <div id="progressText" class="progress-text">Extra tid: 20</div>
            </div>
            <div id="buzzList" class="buzz-list"></div>
            <button class="btn" onclick="resetBuzz()">Nulstil Buzzer</button>
            <button class="btn" onclick="backToBoard()">Tilbage til Brættet</button>
        </div>
    </div>

    <script src="https://cdnjs.cloudflare.com/ajax/libs/microsoft-signalr/6.0.1/signalr.min.js"></script>
    <script>
        const connection = new signalR.HubConnectionBuilder()
            .withUrl("/gameHub")
            .build();

        let gameData = {
            gameCode: '',
            board: null,
            players: {},
            teams: {},
            isTeamMode: false,
            isGameStarted: false,
            buzzTimer: null,
            timeLeft: 10
        };

        // Start connection
        connection.start().then(function () {
            const hostName = localStorage.getItem('hostName') || 'Vært';
            const isTeamMode = localStorage.getItem('isTeamMode') === 'true';
            connection.invoke("CreateGame", hostName, isTeamMode);
        }).catch(function (err) {
            console.error('Connection error:', err);
            alert('Kunne ikke oprette forbindelse til serveren');
        });

        // Event handlers
        connection.on("GameCreated", function (data) {
            gameData.gameCode = data.gameCode;
            gameData.board = data.board;
            gameData.isTeamMode = data.isTeamMode;
            document.getElementById('gameCodeDisplay').textContent = data.gameCode;

            if (gameData.isTeamMode) {
                // Show team lobby, hide game board and players section
                document.getElementById('teamLobby').classList.remove('hidden');
                document.getElementById('gameBoard').classList.add('hidden');
                document.getElementById('playersSection').classList.add('hidden');
            } else {
                // Show game board and players section normally
                document.getElementById('teamLobby').classList.add('hidden');
                document.getElementById('playersSection').classList.remove('hidden');
                renderBoard();
            }
        });

        connection.on("PlayersUpdated", function (players) {
            gameData.players = {};
            players.forEach(p => gameData.players[p.id] = p);

            if (gameData.isTeamMode && !gameData.isGameStarted) {
                updateTeamLobby();
            } else {
                updatePlayersDisplay();
            }
        });

        connection.on("BuzzReceived", function (data) {
            // Start timer only when first buzz is received
            if (data.buzzes.length === 1) {
                startBuzzTimer();
            }
            showBuzzPanel(data.buzzes);
        });

        connection.on("BuzzCleared", function () {
            stopBuzzTimer();
            document.getElementById('buzzPanel').classList.add('hidden');
            document.getElementById('gameBoard').classList.remove('hidden');
        });

        connection.on("ExtendedBuzzTimeExpired", function () {
            stopBuzzTimer();
            // Hide progress bar and show timer with final message
            const timerDisplay = document.getElementById('timerDisplay');
            const progressContainer = document.getElementById('progressContainer');

            progressContainer.style.display = 'none';
            timerDisplay.style.display = 'block';
            timerDisplay.textContent = "I didnt get it";
            timerDisplay.classList.add('expired');
            timerDisplay.style.background = '#666';
        });

        function renderBoard() {
            const board = document.getElementById('gameBoard');
            board.innerHTML = '';

            // Add category headers
            gameData.board.categories.forEach(category => {
                const header = document.createElement('div');
                header.className = 'category-header';
                header.textContent = category.name;
                board.appendChild(header);
            });

            // Add question tiles
            for (let i = 0; i < 5; i++) {
                gameData.board.categories.forEach((category, catIndex) => {
                    const tile = document.createElement('div');
                    const question = category.questions[i];
                    tile.className = `question-tile ${question.isUsed ? 'used' : ''}`;
                    tile.textContent = question.value;

                    if (!question.isUsed) {
                        tile.onclick = () => selectQuestion(catIndex, i);
                    }

                    board.appendChild(tile);
                });
            }
        }

        function selectQuestion(categoryIndex, questionIndex) {
            // Fortæl serveren at et spørgsmål er valgt
            connection.invoke("SelectQuestion", categoryIndex, questionIndex);

            // Vis buzz-panelet og skjul brættet med det samme
            document.getElementById('gameBoard').classList.add('hidden');
            document.getElementById('buzzPanel').classList.remove('hidden');

            // Show waiting state - hide progress bar initially until first buzz
            const timerDisplay = document.getElementById('timerDisplay');
            const buzzList = document.getElementById('buzzList');
            const progressContainer = document.getElementById('progressContainer');

            timerDisplay.style.display = 'block';
            timerDisplay.textContent = "Venter på buzz...";
            timerDisplay.classList.remove('expired');
            timerDisplay.style.background = '#ff6b6b';

            progressContainer.style.display = 'none';
            buzzList.innerHTML = '';
        }

        function startBuzzTimer() {
            // Stop evt. tidligere timer
            stopBuzzTimer();

            gameData.timeLeft = 10;
            const timerDisplay = document.getElementById('timerDisplay');
            const progressContainer = document.getElementById('progressContainer');
            const progressBar = document.getElementById('progressBar');
            const progressText = document.getElementById('progressText');

            // Hide regular timer display and show progress bar for first 10 seconds too
            timerDisplay.style.display = 'none';
            progressContainer.style.display = 'block';

            // Reset progress bar for 10-second timer
            progressBar.style.width = '0%';
            progressBar.style.background = 'linear-gradient(45deg, #ff6b6b, #ee5a24)'; // Red for first timer
            progressText.textContent = `Første buzz: ${gameData.timeLeft}`;

            gameData.buzzTimer = setInterval(() => {
                gameData.timeLeft--;
                progressText.textContent = `Første buzz: ${gameData.timeLeft}`;

                // Calculate progress percentage (0% at start, 100% at end)
                const progressPercent = ((10 - gameData.timeLeft) / 10) * 100;
                progressBar.style.width = progressPercent + '%';

                if (gameData.timeLeft <= 0) {
                    clearInterval(gameData.buzzTimer);
                    gameData.buzzTimer = null;
                    // Immediately transition to extended timer when reaching 0
                    startExtendedBuzzTimer();
                    return; // Exit the interval function
                }
            }, 1000);
        }

        function stopBuzzTimer() {
            if (gameData.buzzTimer) {
                clearInterval(gameData.buzzTimer);
                gameData.buzzTimer = null;
            }
        }

        function startExtendedBuzzTimer() {
            // Stop any existing timer
            stopBuzzTimer();

            gameData.timeLeft = 20;
            const timerDisplay = document.getElementById('timerDisplay');
            const progressContainer = document.getElementById('progressContainer');
            const progressBar = document.getElementById('progressBar');
            const progressText = document.getElementById('progressText');

            // Keep progress bar visible for extended timer too
            progressContainer.style.display = 'block';

            // Reset progress bar for 20-second extended timer
            progressBar.style.width = '0%';
            progressBar.style.background = 'linear-gradient(45deg, #4CAF50, #8BC34A)'; // Green for extended timer
            progressText.textContent = `Extra tid: ${gameData.timeLeft}`;

            gameData.buzzTimer = setInterval(() => {
                gameData.timeLeft--;

                // Stop at 0 and show final message
                if (gameData.timeLeft <= 0) {
                    clearInterval(gameData.buzzTimer);
                    gameData.buzzTimer = null;

                    // Hide progress bar and show timer with final message
                    progressContainer.style.display = 'none';
                    timerDisplay.style.display = 'block';
                    timerDisplay.textContent = "I didnt get it";
                    timerDisplay.classList.add('expired');
                    timerDisplay.style.background = '#666';
                    return; // Exit the interval function
                }

                progressText.textContent = `Extra tid: ${gameData.timeLeft}`;

                // Calculate progress percentage (0% at start, 100% at end)
                const progressPercent = ((20 - gameData.timeLeft) / 20) * 100;
                progressBar.style.width = progressPercent + '%';

                // Change color as time runs out
                if (gameData.timeLeft <= 5) {
                    progressBar.style.background = 'linear-gradient(45deg, #ff9500, #ff6b6b)';
                } else if (gameData.timeLeft <= 10) {
                    progressBar.style.background = 'linear-gradient(45deg, #FFD700, #ff9500)';
                } else {
                    progressBar.style.background = 'linear-gradient(45deg, #4CAF50, #8BC34A)';
                }
            }, 1000);
        }

        function updatePlayersDisplay() {
            const grid = document.getElementById('playersGrid');
            const count = document.getElementById('playerCount');

            const playerList = Object.values(gameData.players);
            count.textContent = playerList.length;

            grid.innerHTML = '';
            playerList.forEach(player => {
                const card = document.createElement('div');
                card.className = 'player-card';
                card.innerHTML = `
                    <h3>${player.name}</h3>
                    <div class="player-score">${player.score} point</div>
                    <div class="score-controls">
                        <input type="number" class="score-input" id="score-${player.id}" placeholder="Point">
                        <button class="btn" onclick="updateScore('${player.id}', true)">+</button>
                        <button class="btn btn-danger" onclick="updateScore('${player.id}', false)">-</button>
                    </div>
                `;
                grid.appendChild(card);
            });
        }

        function updateScore(playerId, isPositive) {
            const input = document.getElementById(`score-${playerId}`);
            const points = parseInt(input.value) || 0;
            if (points === 0) return;

            const finalPoints = isPositive ? points : -points;
            connection.invoke("UpdateScore", playerId, finalPoints);
            input.value = '';
        }

        function showBuzzPanel(buzzes) {
            document.getElementById('gameBoard').classList.add('hidden');
            document.getElementById('buzzPanel').classList.remove('hidden');

            const timerDisplay = document.getElementById('timerDisplay');
            const buzzList = document.getElementById('buzzList');

            // If no buzzes yet, show waiting state
            if (buzzes.length === 0) {
                timerDisplay.textContent = "Venter på buzz...";
                timerDisplay.classList.remove('expired');
            }

            buzzList.innerHTML = '';

            buzzes.forEach(buzz => {
                const item = document.createElement('div');
                item.className = 'buzz-item';
                item.innerHTML = `
                    <span>${buzz.playerName}</span>
                    <span class="buzz-order">${buzz.order}</span>
                `;
                buzzList.appendChild(item);
            });
        }

        function resetBuzz() {
            stopBuzzTimer();
            // Hide progress bar and reset timer display
            document.getElementById('progressContainer').style.display = 'none';
            document.getElementById('timerDisplay').style.display = 'block';
            connection.invoke("ResetBuzz");
        }

        function backToBoard() {
            stopBuzzTimer();
            document.getElementById('buzzPanel').classList.add('hidden');
            document.getElementById('gameBoard').classList.remove('hidden');

            // Reset timer display style and hide progress bar
            const timerDisplay = document.getElementById('timerDisplay');
            const progressContainer = document.getElementById('progressContainer');
            timerDisplay.style.background = '#ff6b6b';
            timerDisplay.style.display = 'block';
            progressContainer.style.display = 'none';

            // Notify players to return to board view
            connection.invoke("HostReturnToBoard");
        }

        function endGame() {
            if (confirm('Er du sikker på, at du vil afslutte spillet?')) {
                window.location.href = '/';
            }
        }

        // Update board when questions are used
        connection.on("QuestionSelected", function (data) {
            gameData.board = data.board;
            renderBoard();
        });

        connection.on("ScoreUpdated", function (data) {
            if (gameData.isTeamMode && data.teams) {
                // Update teams and players
                gameData.teams = {};
                data.teams.forEach(t => gameData.teams[t.id] = t);
                gameData.players = {};
                data.players.forEach(p => gameData.players[p.id] = p);
                updateTeamPlayersDisplay();
            } else {
                // Solo mode
                gameData.players[data.playerId] = {
                    id: data.playerId,
                    name: data.playerName,
                    score: data.newScore
                };
                updatePlayersDisplay();
            }
        });

        // Team mode event handlers
        connection.on("TeamCreated", function (data) {
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            updateTeamLobby();
        });

        connection.on("TeamsUpdated", function (data) {
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            gameData.players = {};
            data.players.forEach(p => gameData.players[p.id] = p);
            updateTeamLobby();
        });

        connection.on("GameStarted", function (data) {
            gameData.isGameStarted = true;
            gameData.board = data.board;
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            gameData.players = {};
            data.players.forEach(p => gameData.players[p.id] = p);

            // Hide team lobby, show game board and team display
            document.getElementById('teamLobby').classList.add('hidden');
            document.getElementById('gameBoard').classList.remove('hidden');
            document.getElementById('playersSection').classList.remove('hidden');

            renderBoard();
            updateTeamPlayersDisplay();
        });

        // Team management functions
        function createTeam() {
            const teamNameInput = document.getElementById('teamName');
            const teamColorInput = document.getElementById('teamColor');
            const teamName = teamNameInput.value.trim();
            const teamColor = teamColorInput.value;

            if (!teamName) {
                alert('Indtast venligst et holdnavn');
                return;
            }

            connection.invoke("CreateTeam", teamName, teamColor);
            teamNameInput.value = '';
        }

        function startGame() {
            if (Object.keys(gameData.teams).length === 0) {
                alert('Opret mindst ét hold før du starter spillet');
                return;
            }

            const teamsWithPlayers = Object.values(gameData.teams).filter(t => t.playerIds.length > 0);
            if (teamsWithPlayers.length === 0) {
                alert('Mindst ét hold skal have spillere før du starter spillet');
                return;
            }

            connection.invoke("StartGame");
        }

        function updateTeamLobby() {
            // Update teams grid
            const teamsGrid = document.getElementById('teamsGrid');
            teamsGrid.innerHTML = '';

            Object.values(gameData.teams).forEach(team => {
                const teamCard = document.createElement('div');
                teamCard.className = 'team-card';
                teamCard.style.borderLeftColor = team.color;

                const teamPlayers = Object.values(gameData.players).filter(p => p.teamId === team.id);

                teamCard.innerHTML = `
                    <h3 style="color: ${team.color}">${team.name}</h3>
                    <div class="team-members">
                        ${teamPlayers.length === 0 ? '<em>Ingen spillere endnu</em>' : ''}
                        ${teamPlayers.map(p => `<div class="team-member">${p.name}</div>`).join('')}
                    </div>
                `;
                teamsGrid.appendChild(teamCard);
            });

            // Update waiting players
            const waitingPlayersDiv = document.getElementById('waitingPlayers');
            const waitingPlayers = Object.values(gameData.players).filter(p => !p.teamId);

            if (waitingPlayers.length === 0) {
                waitingPlayersDiv.innerHTML = 'Ingen spillere venter endnu...';
            } else {
                waitingPlayersDiv.innerHTML = waitingPlayers.map(p => 
                    `<span class="waiting-player">${p.name}</span>`
                ).join('');
            }
        }

        function updateTeamPlayersDisplay() {
            const grid = document.getElementById('playersGrid');
            const count = document.getElementById('playerCount');

            // Group by teams
            const teamsList = Object.values(gameData.teams);
            count.textContent = `${Object.keys(gameData.players).length} spillere i ${teamsList.length} hold`;

            grid.innerHTML = '';
            teamsList.forEach(team => {
                const card = document.createElement('div');
                card.className = 'player-card';
                card.style.borderLeft = `5px solid ${team.color}`;

                const teamPlayers = Object.values(gameData.players).filter(p => p.teamId === team.id);
                const playerNames = teamPlayers.map(p => p.name).join(', ');

                card.innerHTML = `
                    <h3 style="color: ${team.color}">${team.name}</h3>
                    <div style="font-size: 0.9em; margin: 5px 0;">${playerNames}</div>
                    <div class="player-score">${team.score} point</div>
                    <div class="score-controls">
                        <input type="number" class="score-input" id="score-team-${team.id}" placeholder="Point">
                        <button class="btn" onclick="updateTeamScore('${team.id}', true)">+</button>
                        <button class="btn btn-danger" onclick="updateTeamScore('${team.id}', false)">-</button>
                    </div>
                `;
                grid.appendChild(card);
            });
        }

        function updateTeamScore(teamId, isPositive) {
            // Find first player in team to use as reference for score update
            const team = gameData.teams[teamId];
            if (!team || !team.playerIds || team.playerIds.length === 0) return;

            const firstPlayerId = team.playerIds[0];
            const input = document.getElementById(`score-team-${teamId}`);
            const points = parseInt(input.value) || 0;
            if (points === 0) return;

            const finalPoints = isPositive ? points : -points;
            connection.invoke("UpdateScore", firstPlayerId, finalPoints);
            input.value = '';
        }

        // Prevent zoom on double-tap on iOS
        let lastTouchEnd = 0;
        document.addEventListener('touchend', function (event) {
            const now = (new Date()).getTime();
            if (now - lastTouchEnd <= 300) {
                event.preventDefault();
            }
            lastTouchEnd = now;
        }, false);
    </script>
</body>
</html>

﻿@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="da">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no, maximum-scale=1.0">
    <title>Jeopardy - Vært</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Arial', sans-serif;
            background: linear-gradient(135deg, #1e3c72, #2a5298);
            color: white;
            min-height: 100vh;
            padding: 20px;
            touch-action: manipulation;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
        }

        .host-header {
            text-align: center;
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 15px;
            margin-bottom: 20px;
            backdrop-filter: blur(10px);
        }

        .game-code {
            font-size: 2.5em;
            color: #FFD700;
            font-weight: bold;
            background: rgba(0, 0, 0, 0.3);
            padding: 15px;
            border-radius: 10px;
            margin: 10px 0;
        }

        .players-section {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 15px;
            margin-bottom: 20px;
            backdrop-filter: blur(10px);
        }

        .players-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 15px;
            margin-top: 15px;
        }

        .player-card {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            text-align: center;
        }

        .player-score {
            font-size: 1.5em;
            color: #FFD700;
            font-weight: bold;
        }

        .game-board {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 10px;
            margin: 20px 0;
        }

        .category-header {
            background: #FFD700;
            color: #000;
            padding: 20px;
            text-align: center;
            font-weight: bold;
            font-size: 1.1em;
            border-radius: 8px;
            text-transform: uppercase;
        }

        .question-tile {
            background: #000080;
            color: #FFD700;
            padding: 30px;
            text-align: center;
            font-size: 1.8em;
            font-weight: bold;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.3s ease;
            border: 3px solid #FFD700;
        }

            .question-tile:hover {
                background: #0000CD;
                transform: scale(1.05);
            }

            .question-tile.used {
                background: #333;
                color: #666;
                cursor: not-allowed;
                opacity: 0.5;
            }

        .buzz-panel {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 15px;
            margin-top: 20px;
            backdrop-filter: blur(10px);
        }

        /* Simple Countdown Timer */
        .countdown-timer {
            background: rgba(255, 107, 107, 0.2);
            padding: 20px;
            border-radius: 15px;
            margin: 15px 0;
            text-align: center;
            border: 3px solid #ff6b6b;
        }

        .countdown-display {
            font-size: 4em;
            font-weight: bold;
            color: #ff6b6b;
            text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
            margin: 10px 0;
        }

        .countdown-display.warning {
            color: #ff9500;
            animation: pulse 0.5s infinite;
        }

        .countdown-display.critical {
            color: #ff0000;
            animation: pulse 0.3s infinite;
        }

        @@keyframes pulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.1); }
        }

        .buzz-list {
            margin: 15px 0;
        }

        .buzz-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 8px;
            margin: 5px 0;
        }

        .buzz-order {
            background: #FFD700;
            color: #000;
            padding: 8px 12px;
            border-radius: 50%;
            font-weight: bold;
        }

        .btn {
            background: linear-gradient(45deg, #667eea, #764ba2);
            border: none;
            color: white;
            padding: 12px 25px;
            font-size: 1em;
            border-radius: 8px;
            cursor: pointer;
            margin: 5px;
            transition: all 0.3s ease;
        }

            .btn:hover {
                transform: translateY(-2px);
                box-shadow: 0 8px 15px rgba(0, 0, 0, 0.3);
            }

        .btn-danger {
            background: linear-gradient(45deg, #ff6b6b, #ee5a24);
        }

        .score-controls {
            display: flex;
            gap: 10px;
            margin-top: 10px;
        }

        .score-input {
            width: 80px;
            padding: 5px;
            border-radius: 4px;
            border: none;
            text-align: center;
        }

        .hidden {
            display: none;
        }

        /* Team Mode Styles - Modern Design */
        .team-lobby {
            background: linear-gradient(135deg, rgba(102, 126, 234, 0.2), rgba(118, 75, 162, 0.2));
            padding: 30px;
            border-radius: 25px;
            margin-bottom: 20px;
            backdrop-filter: blur(15px);
            box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
            border: 2px solid rgba(255, 255, 255, 0.2);
        }

        .team-lobby h2 {
            font-size: 2em;
            margin-bottom: 25px;
            text-align: center;
            text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
        }

        .team-creation {
            background: rgba(255, 255, 255, 0.15);
            padding: 25px;
            border-radius: 15px;
            margin-bottom: 30px;
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
        }

        .team-creation h3 {
            margin-bottom: 15px;
            font-size: 1.3em;
        }

        .team-input-group {
            display: flex;
            gap: 15px;
            margin: 15px 0;
            flex-wrap: wrap;
        }

        .team-input-group input {
            flex: 1;
            min-width: 180px;
            padding: 12px 18px;
            border-radius: 10px;
            border: 2px solid rgba(255, 255, 255, 0.3);
            font-size: 1.05em;
            background: rgba(255, 255, 255, 0.9);
            transition: all 0.3s ease;
        }

        .team-input-group input:focus {
            outline: none;
            border-color: #FFD700;
            transform: scale(1.02);
        }

        .team-input-group input[type="color"] {
            min-width: 80px;
            height: 50px;
            cursor: pointer;
        }

        .teams-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 20px;
            margin-top: 20px;
        }

        .team-card {
            background: rgba(255, 255, 255, 0.15);
            padding: 20px;
            border-radius: 15px;
            border-left: 6px solid;
            box-shadow: 0 5px 20px rgba(0, 0, 0, 0.2);
            transition: all 0.3s ease;
        }

        .team-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
        }

        .team-card h3 {
            font-size: 1.4em;
            margin-bottom: 10px;
        }

        .team-members {
            margin-top: 15px;
            font-size: 0.95em;
        }

        .team-member {
            background: rgba(255, 255, 255, 0.2);
            padding: 8px 14px;
            border-radius: 8px;
            margin: 6px 0;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .team-member::before {
            content: '';
            font-size: 1.2em;
        }

        .waiting-players {
            background: rgba(255, 215, 0, 0.15);
            padding: 20px;
            border-radius: 15px;
            margin-top: 20px;
            border: 2px dashed rgba(255, 215, 0, 0.5);
        }

        .waiting-players h3 {
            margin-bottom: 15px;
            font-size: 1.3em;
        }

        .waiting-player {
            background: rgba(255, 255, 255, 0.2);
            padding: 10px 16px;
            border-radius: 20px;
            margin: 8px 5px;
            display: inline-flex;
            align-items: center;
            gap: 8px;
            animation: pulse 2s infinite;
        }

        .waiting-player::before {
            content: '⏳';
            font-size: 1.1em;
        }

        /* Music Controls */
        .music-controls {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            margin: 15px 0;
            text-align: center;
        }

        .music-controls button {
            margin: 5px;
        }

        .answer-display {
            background: rgba(255, 215, 0, 0.3);
            padding: 15px;
            border-radius: 10px;
            margin: 10px 0;
            font-size: 1.5em;
            font-weight: bold;
            border: 2px solid #FFD700;
            text-align: center;
        }

        .btn-music {
            background: linear-gradient(45deg, #9b59b6, #8e44ad);
        }

        .btn-answer {
            background: linear-gradient(45deg, #FFD700, #FFA500);
            color: #000;
        }

        @@media (max-width: 768px) {
            body {
                padding: 10px;
            }

            .game-board {
                grid-template-columns: repeat(2, 1fr);
                gap: 6px;
            }

            .question-tile {
                padding: 15px 8px;
                font-size: 1.2em;
                min-height: 50px;
            }

            .category-header {
                padding: 8px 4px;
                font-size: 0.8em;
            }

            .players-grid {
                grid-template-columns: 1fr;
            }

            .game-code {
                font-size: 2em;
                padding: 10px;
            }

            .host-header, .players-section, .buzz-panel {
                padding: 15px;
                margin-bottom: 15px;
            }

            .player-card {
                padding: 10px;
            }

            .btn {
                padding: 10px 20px;
                font-size: 0.9em;
                margin: 3px;
            }

            .buzz-item {
                padding: 10px;
                font-size: 0.9em;
            }

            .score-controls {
                flex-direction: column;
                gap: 5px;
            }

            .score-input {
                width: 100%;
                margin-bottom: 5px;
            }
        }

        @@media (max-width: 480px) {
            body {
                padding: 5px;
            }

            .container {
                max-width: 100%;
            }

            .game-board {
                grid-template-columns: repeat(2, 1fr);
                gap: 4px;
            }

            .question-tile {
                padding: 10px 6px;
                font-size: 1em;
                min-height: 45px;
            }

            .category-header {
                padding: 6px 2px;
                font-size: 0.7em;
            }

            .game-code {
                font-size: 1.6em;
                padding: 8px;
            }

            .host-header h1 {
                font-size: 1.5em;
            }

            .players-section h2 {
                font-size: 1.2em;
            }

            .buzz-panel h2 {
                font-size: 1.2em;
            }

            .timer-display {
                font-size: 1.2em;
                padding: 8px 15px;
            }

            .btn {
                padding: 8px 15px;
                font-size: 0.8em;
                margin: 2px;
            }

            .buzz-item {
                padding: 8px;
                font-size: 0.8em;
            }

            .buzz-order {
                padding: 6px 10px;
            }

            .player-score {
                font-size: 1.2em;
            }
        }

        @@media (max-width: 896px) and (orientation: landscape) {
            .game-board {
                grid-template-columns: repeat(5, 1fr);
                gap: 3px;
            }

            .question-tile {
                padding: 8px 4px;
                font-size: 0.9em;
                min-height: 40px;
            }

            .category-header {
                padding: 4px 2px;
                font-size: 0.6em;
            }

            .players-grid {
                grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="host-header">
            <h1> Jeopardy Vært</h1>
            <div class="game-code">Spil Kode: <span id="gameCodeDisplay">----</span></div>
            <button class="btn btn-danger" onclick="endGame()">Afslut Spil</button>
        </div>

        <!-- Team Lobby (shown only in team mode before game starts) -->
        <div id="teamLobby" class="team-lobby hidden">
            <h2>Hold Opsætning</h2>
            <div class="team-creation">
                <h3>Opret Hold</h3>
                <div class="team-input-group">
                    <input type="text" id="teamName" placeholder="Hold navn" maxlength="30">
                    <input type="color" id="teamColor" value="#667eea">
                    <button class="btn" onclick="createTeam()">Opret Hold</button>
                </div>
            </div>
            <div id="teamsGrid" class="teams-grid"></div>
            <div class="waiting-players">
                <h3>Ventende Spillere</h3>
                <div id="waitingPlayers">Ingen spillere venter endnu...</div>
            </div>
            <button class="btn" onclick="startGame()" style="background: linear-gradient(45deg, #4CAF50, #8BC34A); width: 100%; margin-top: 20px; font-size: 1.2em;">Start Spil</button>
        </div>

        <div class="players-section" id="playersSection">
            <h2>Spillere (<span id="playerCount">0</span>)</h2>
            <div id="playersGrid" class="players-grid"></div>
        </div>

        <div id="gameBoard" class="game-board"></div>

        <div id="buzzPanel" class="buzz-panel hidden">
            <h2>Spillere der buzzede:</h2>

            <!-- Music Controls -->
            <div id="musicControls" class="music-controls hidden">
                <h3> Musik Kontrol</h3>
                <button class="btn btn-music" onclick="startMusicManually()">▶️ Start Musik</button>
                <button class="btn btn-music" onclick="stopMusicManually()">⏹️ Stop Musik</button>
                <button class="btn btn-answer" onclick="revealAnswer()"> Vis Svar</button>
                <div id="answerDisplay" class="answer-display hidden"></div>
            </div>

            <!-- Simple countdown timer -->
            <div id="countdownTimer" class="countdown-timer hidden">
                <h2>⏱️ Timer</h2>
                <div id="countdownDisplay" class="countdown-display">10</div>
            </div>

            <div id="buzzList" class="buzz-list"></div>
            <button class="btn" onclick="resetBuzz()">Nulstil Buzzer</button>
            <button class="btn" onclick="backToBoard()">Tilbage til Brættet</button>
        </div>

        <!-- Hidden audio player -->
        <audio id="musicPlayer" style="display: none;"></audio>
    </div>

    <script src="https://cdnjs.cloudflare.com/ajax/libs/microsoft-signalr/6.0.1/signalr.min.js"></script>
    <script>
        const connection = new signalR.HubConnectionBuilder()
            .withUrl("/gameHub")
            .build();

        let gameData = {
            gameCode: '',
            board: null,
            players: {},
            teams: {},
            isTeamMode: false,
            isGameStarted: false,
            countdownTimer: null,
            timeLeft: 10,
            currentMusicFile: null,
            currentAnswer: null,
            musicPlayer: null
        };

        // Initialize music player
        gameData.musicPlayer = document.getElementById('musicPlayer');

        // Start connection
        connection.start().then(function () {
            const hostName = localStorage.getItem('hostName') || 'Vært';
            const isTeamMode = localStorage.getItem('isTeamMode') === 'true';
            connection.invoke("CreateGame", hostName, isTeamMode);
        }).catch(function (err) {
            console.error('Connection error:', err);
            alert('Kunne ikke oprette forbindelse til serveren');
        });

        // Event handlers
        connection.on("GameCreated", function (data) {
            gameData.gameCode = data.gameCode;
            gameData.board = data.board;
            gameData.isTeamMode = data.isTeamMode;
            document.getElementById('gameCodeDisplay').textContent = data.gameCode;

            if (gameData.isTeamMode) {
                // Show team lobby, hide game board and players section
                document.getElementById('teamLobby').classList.remove('hidden');
                document.getElementById('gameBoard').classList.add('hidden');
                document.getElementById('playersSection').classList.add('hidden');
            } else {
                // Show game board and players section normally
                document.getElementById('teamLobby').classList.add('hidden');
                document.getElementById('playersSection').classList.remove('hidden');
                renderBoard();
            }
        });

        connection.on("PlayersUpdated", function (players) {
            gameData.players = {};
            players.forEach(p => gameData.players[p.id] = p);

            if (gameData.isTeamMode && !gameData.isGameStarted) {
                updateTeamLobby();
            } else {
                updatePlayersDisplay();
            }
        });

        connection.on("BuzzReceived", function (data) {
            // Start simple countdown timer when team/player buzzes
            startCountdown();
            showBuzzPanel(data.buzzes);
        });

        connection.on("BuzzCleared", function () {
            stopBuzzTimer();
            document.getElementById('buzzPanel').classList.add('hidden');
            document.getElementById('gameBoard').classList.remove('hidden');
        });

        connection.on("ExtendedBuzzTimeExpired", function () {
            stopBuzzTimer();
            // Hide progress bar and show timer with final message
            const timerDisplay = document.getElementById('timerDisplay');
            const progressContainer = document.getElementById('progressContainer');

            progressContainer.style.display = 'none';
            timerDisplay.style.display = 'block';
            timerDisplay.textContent = "I didnt get it";
            timerDisplay.classList.add('expired');
            timerDisplay.style.background = '#666';
        });

        // Removed complex timer event handlers - using simple countdown now

        // Music event handlers
        connection.on("PlayMusic", function (data) {
            gameData.currentMusicFile = data.musicFile;
            gameData.currentAnswer = data.answer;

            if (gameData.musicPlayer && data.musicFile) {
                gameData.musicPlayer.src = data.musicFile;
                gameData.musicPlayer.loop = true;
                gameData.musicPlayer.play().catch(err => console.error('Music play error:', err));

                // Show music controls
                document.getElementById('musicControls').classList.remove('hidden');
                document.getElementById('answerDisplay').classList.add('hidden');
            }
        });

        // Music is now controlled manually by host - no automatic stop/resume

        function renderBoard() {
            const board = document.getElementById('gameBoard');
            board.innerHTML = '';

            // Add category headers
            gameData.board.categories.forEach(category => {
                const header = document.createElement('div');
                header.className = 'category-header';
                header.textContent = category.name;
                board.appendChild(header);
            });

            // Add question tiles
            for (let i = 0; i < 5; i++) {
                gameData.board.categories.forEach((category, catIndex) => {
                    const tile = document.createElement('div');
                    const question = category.questions[i];
                    tile.className = `question-tile ${question.isUsed ? 'used' : ''}`;
                    tile.textContent = question.value;

                    if (!question.isUsed) {
                        tile.onclick = () => selectQuestion(catIndex, i);
                    }

                    board.appendChild(tile);
                });
            }
        }

        function selectQuestion(categoryIndex, questionIndex) {
            // Fortæl serveren at et spørgsmål er valgt
            connection.invoke("SelectQuestion", categoryIndex, questionIndex);

            // Vis buzz-panelet og skjul brættet med det samme
            document.getElementById('gameBoard').classList.add('hidden');
            document.getElementById('buzzPanel').classList.remove('hidden');

            // Hide countdown timer initially
            document.getElementById('countdownTimer').classList.add('hidden');
            document.getElementById('buzzList').innerHTML = '';
        }

        // Old complex timer functions removed - using simple countdown now

        function updatePlayersDisplay() {
            const grid = document.getElementById('playersGrid');
            const count = document.getElementById('playerCount');

            const playerList = Object.values(gameData.players);
            count.textContent = playerList.length;

            grid.innerHTML = '';
            playerList.forEach(player => {
                const card = document.createElement('div');
                card.className = 'player-card';
                card.innerHTML = `
                    <h3>${player.name}</h3>
                    <div class="player-score">${player.score} point</div>
                    <div class="score-controls">
                        <input type="number" class="score-input" id="score-${player.id}" placeholder="Point">
                        <button class="btn" onclick="updateScore('${player.id}', true)">+</button>
                        <button class="btn btn-danger" onclick="updateScore('${player.id}', false)">-</button>
                    </div>
                `;
                grid.appendChild(card);
            });
        }

        function updateScore(playerId, isPositive) {
            const input = document.getElementById(`score-${playerId}`);
            const points = parseInt(input.value) || 0;
            if (points === 0) return;

            const finalPoints = isPositive ? points : -points;
            connection.invoke("UpdateScore", playerId, finalPoints);
            input.value = '';
        }

        function showBuzzPanel(buzzes) {
            document.getElementById('gameBoard').classList.add('hidden');
            document.getElementById('buzzPanel').classList.remove('hidden');

            const timerDisplay = document.getElementById('timerDisplay');
            const buzzList = document.getElementById('buzzList');

            // If no buzzes yet, show waiting state
            if (buzzes.length === 0) {
                timerDisplay.textContent = "Venter på buzz...";
                timerDisplay.classList.remove('expired');
            }

            buzzList.innerHTML = '';

            buzzes.forEach(buzz => {
                const item = document.createElement('div');
                item.className = 'buzz-item';
                item.innerHTML = `
                    <span>${buzz.playerName}</span>
                    <span class="buzz-order">${buzz.order}</span>
                `;
                buzzList.appendChild(item);
            });
        }

        function resetBuzz() {
            stopCountdown();
            // Stop music
            if (gameData.musicPlayer) {
                gameData.musicPlayer.pause();
                gameData.musicPlayer.currentTime = 0;
            }
            // Hide music controls and countdown
            document.getElementById('musicControls').classList.add('hidden');
            document.getElementById('answerDisplay').classList.add('hidden');
            document.getElementById('countdownTimer').classList.add('hidden');
            gameData.currentMusicFile = null;
            gameData.currentAnswer = null;

            connection.invoke("ResetBuzz");
        }

        function backToBoard() {
            stopCountdown();

            // Stop music
            if (gameData.musicPlayer) {
                gameData.musicPlayer.pause();
                gameData.musicPlayer.currentTime = 0;
            }
            // Hide music controls and countdown
            document.getElementById('musicControls').classList.add('hidden');
            document.getElementById('answerDisplay').classList.add('hidden');
            document.getElementById('countdownTimer').classList.add('hidden');
            gameData.currentMusicFile = null;
            gameData.currentAnswer = null;

            document.getElementById('buzzPanel').classList.add('hidden');
            document.getElementById('gameBoard').classList.remove('hidden');

            // Notify players to return to board view
            connection.invoke("HostReturnToBoard");
        }

        function endGame() {
            if (confirm('Er du sikker på, at du vil afslutte spillet?')) {
                window.location.href = '/';
            }
        }

        // Update board when questions are used
        connection.on("QuestionSelected", function (data) {
            gameData.board = data.board;
            renderBoard();
        });

        connection.on("ScoreUpdated", function (data) {
            if (gameData.isTeamMode && data.teams) {
                // Update teams and players
                gameData.teams = {};
                data.teams.forEach(t => gameData.teams[t.id] = t);
                gameData.players = {};
                data.players.forEach(p => gameData.players[p.id] = p);
                updateTeamPlayersDisplay();
            } else {
                // Solo mode
                gameData.players[data.playerId] = {
                    id: data.playerId,
                    name: data.playerName,
                    score: data.newScore
                };
                updatePlayersDisplay();
            }
        });

        // Music control functions
        function startMusicManually() {
            if (gameData.musicPlayer && gameData.currentMusicFile) {
                gameData.musicPlayer.play().catch(err => console.error('Music play error:', err));
            }
        }

        function stopMusicManually() {
            if (gameData.musicPlayer) {
                gameData.musicPlayer.pause();
            }
        }

        function revealAnswer() {
            const answerDisplay = document.getElementById('answerDisplay');
            if (gameData.currentAnswer) {
                answerDisplay.textContent = ` Svar: ${gameData.currentAnswer}`;
                answerDisplay.classList.remove('hidden');
            } else {
                answerDisplay.textContent = ' Ingen svar tilgængeligt';
                answerDisplay.classList.remove('hidden');
            }
        }

        // Simple countdown timer functions
        function startCountdown() {
            // Stop music when countdown starts
            if (gameData.musicPlayer) {
                gameData.musicPlayer.pause();
            }

            // Stop any existing countdown
            stopCountdown();

            // Show countdown timer
            document.getElementById('countdownTimer').classList.remove('hidden');

            // Reset to 10 seconds
            gameData.timeLeft = 10;
            const countdownDisplay = document.getElementById('countdownDisplay');
            countdownDisplay.textContent = gameData.timeLeft;
            countdownDisplay.classList.remove('warning', 'critical');

            // Start countdown
            gameData.countdownTimer = setInterval(() => {
                gameData.timeLeft--;
                countdownDisplay.textContent = gameData.timeLeft;

                // Visual warnings
                if (gameData.timeLeft <= 3) {
                    countdownDisplay.classList.add('critical');
                    countdownDisplay.classList.remove('warning');
                } else if (gameData.timeLeft <= 5) {
                    countdownDisplay.classList.add('warning');
                    countdownDisplay.classList.remove('critical');
                }

                // Stop at 0
                if (gameData.timeLeft <= 0) {
                    stopCountdown();
                    // Hide timer and notify players they can buzz again
                    document.getElementById('countdownTimer').classList.add('hidden');
                    connection.invoke("NotifyAnswerTimeUp");
                }
            }, 1000);
        }

        function stopCountdown() {
            if (gameData.countdownTimer) {
                clearInterval(gameData.countdownTimer);
                gameData.countdownTimer = null;
            }
        }

        // Team mode event handlers
        connection.on("TeamCreated", function (data) {
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            updateTeamLobby();
        });

        connection.on("TeamsUpdated", function (data) {
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            gameData.players = {};
            data.players.forEach(p => gameData.players[p.id] = p);
            updateTeamLobby();
        });

        connection.on("GameStarted", function (data) {
            gameData.isGameStarted = true;
            gameData.board = data.board;
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            gameData.players = {};
            data.players.forEach(p => gameData.players[p.id] = p);

            // Hide team lobby, show game board and team display
            document.getElementById('teamLobby').classList.add('hidden');
            document.getElementById('gameBoard').classList.remove('hidden');
            document.getElementById('playersSection').classList.remove('hidden');

            renderBoard();
            updateTeamPlayersDisplay();
        });

        // Team management functions
        function createTeam() {
            const teamNameInput = document.getElementById('teamName');
            const teamColorInput = document.getElementById('teamColor');
            const teamName = teamNameInput.value.trim();
            const teamColor = teamColorInput.value;

            if (!teamName) {
                alert('Indtast venligst et holdnavn');
                return;
            }

            connection.invoke("CreateTeam", teamName, teamColor);
            teamNameInput.value = '';
        }

        function startGame() {
            if (Object.keys(gameData.teams).length === 0) {
                alert('Opret mindst ét hold før du starter spillet');
                return;
            }

            const teamsWithPlayers = Object.values(gameData.teams).filter(t => t.playerIds.length > 0);
            if (teamsWithPlayers.length === 0) {
                alert('Mindst ét hold skal have spillere før du starter spillet');
                return;
            }

            connection.invoke("StartGame");
        }

        function updateTeamLobby() {
            // Update teams grid
            const teamsGrid = document.getElementById('teamsGrid');
            teamsGrid.innerHTML = '';

            Object.values(gameData.teams).forEach(team => {
                const teamCard = document.createElement('div');
                teamCard.className = 'team-card';
                teamCard.style.borderLeftColor = team.color;

                const teamPlayers = Object.values(gameData.players).filter(p => p.teamId === team.id);

                teamCard.innerHTML = `
                    <h3 style="color: ${team.color}">${team.name}</h3>
                    <div class="team-members">
                        ${teamPlayers.length === 0 ? '<em>Ingen spillere endnu</em>' : ''}
                        ${teamPlayers.map(p => `<div class="team-member">${p.name}</div>`).join('')}
                    </div>
                `;
                teamsGrid.appendChild(teamCard);
            });

            // Update waiting players
            const waitingPlayersDiv = document.getElementById('waitingPlayers');
            const waitingPlayers = Object.values(gameData.players).filter(p => !p.teamId);

            if (waitingPlayers.length === 0) {
                waitingPlayersDiv.innerHTML = 'Ingen spillere venter endnu...';
            } else {
                waitingPlayersDiv.innerHTML = waitingPlayers.map(p => 
                    `<span class="waiting-player">${p.name}</span>`
                ).join('');
            }
        }

        function updateTeamPlayersDisplay() {
            const grid = document.getElementById('playersGrid');
            const count = document.getElementById('playerCount');

            // Group by teams
            const teamsList = Object.values(gameData.teams);
            count.textContent = `${Object.keys(gameData.players).length} spillere i ${teamsList.length} hold`;

            grid.innerHTML = '';
            teamsList.forEach(team => {
                const card = document.createElement('div');
                card.className = 'player-card';
                card.style.borderLeft = `5px solid ${team.color}`;

                const teamPlayers = Object.values(gameData.players).filter(p => p.teamId === team.id);
                const playerNames = teamPlayers.map(p => p.name).join(', ');

                card.innerHTML = `
                    <h3 style="color: ${team.color}">${team.name}</h3>
                    <div style="font-size: 0.9em; margin: 5px 0;">${playerNames}</div>
                    <div class="player-score">${team.score} point</div>
                    <div class="score-controls">
                        <input type="number" class="score-input" id="score-team-${team.id}" placeholder="Point">
                        <button class="btn" onclick="updateTeamScore('${team.id}', true)">+</button>
                        <button class="btn btn-danger" onclick="updateTeamScore('${team.id}', false)">-</button>
                    </div>
                `;
                grid.appendChild(card);
            });
        }

        function updateTeamScore(teamId, isPositive) {
            // Find first player in team to use as reference for score update
            const team = gameData.teams[teamId];
            if (!team || !team.playerIds || team.playerIds.length === 0) return;

            const firstPlayerId = team.playerIds[0];
            const input = document.getElementById(`score-team-${teamId}`);
            const points = parseInt(input.value) || 0;
            if (points === 0) return;

            const finalPoints = isPositive ? points : -points;
            connection.invoke("UpdateScore", firstPlayerId, finalPoints);
            input.value = '';
        }

        // Prevent zoom on double-tap on iOS
        let lastTouchEnd = 0;
        document.addEventListener('touchend', function (event) {
            const now = (new Date()).getTime();
            if (now - lastTouchEnd <= 300) {
                event.preventDefault();
            }
            lastTouchEnd = now;
        }, false);
    </script>
</body>
</html>

﻿@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="da">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Jeopardy Spil</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Arial', sans-serif;
            background: linear-gradient(135deg, #1e3c72, #2a5298);
            color: white;
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .container {
            max-width: 600px;
            width: 95%;
            margin: 0 auto;
            padding: 20px;
        }

        .login-screen {
            text-align: center;
            background: rgba(255, 255, 255, 0.1);
            padding: 40px;
            border-radius: 15px;
            backdrop-filter: blur(10px);
            box-shadow: 0 8px 32px rgba(31, 38, 135, 0.37);
        }

        h1 {
            margin-bottom: 30px;
            font-size: 3em;
            text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.5);
        }

        .input-group {
            margin: 20px 0;
        }

            .input-group input {
                width: 100%;
                padding: 15px;
                border: none;
                border-radius: 8px;
                font-size: 1.1em;
                margin: 10px 0;
            }

        .btn {
            background: linear-gradient(45deg, #667eea, #764ba2);
            border: none;
            color: white;
            padding: 15px 30px;
            font-size: 1.1em;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.3s ease;
            margin: 10px;
            width: 250px;
        }

            .btn:hover {
                transform: translateY(-3px);
                box-shadow: 0 10px 20px rgba(0, 0, 0, 0.3);
            }

        .btn-host {
            background: linear-gradient(45deg, #f093fb, #f5576c);
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="login-screen">
            <h1> Jeopardy Spil</h1>
            <div class="input-group">
                <input type="text" id="playerName" placeholder="Indtast dit navn" maxlength="20">
                <input type="text" id="gameCode" placeholder="Spil kode (kun for spillere)">
                <button class="btn" onclick="joinAsPlayer()">Tilslut som spiller</button>
                <button class="btn btn-host" onclick="createAsHost(false)">Opret solo spil som vært</button>
                <button class="btn btn-host" onclick="createAsHost(true)" style="background: linear-gradient(45deg, #667eea, #764ba2);">Opret hold spil som vært</button>
            </div>
        </div>
    </div>

    <script>
        function joinAsPlayer() {
            const name = document.getElementById('playerName').value.trim();
            const code = document.getElementById('gameCode').value.trim();

            if (!name || !code) {
                alert('Indtast venligst navn og spil kode');
                return;
            }

            localStorage.setItem('playerName', name);
            localStorage.setItem('gameCode', code);
            window.location.href = '/Home/Play';
        }

        function createAsHost(isTeamMode) {
            const name = document.getElementById('playerName').value.trim();

            if (!name) {
                alert('Indtast venligst dit navn');
                return;
            }

            localStorage.setItem('hostName', name);
            localStorage.setItem('isTeamMode', isTeamMode ? 'true' : 'false');
            window.location.href = '/Home/Host';
        }

        // Make buttons responsive on mobile
        function checkMobile() {
            const buttons = document.querySelectorAll('.btn');
            if (window.innerWidth <= 768) {
                buttons.forEach(btn => {
                    btn.style.width = '100%';
                });
            } else {
                buttons.forEach(btn => {
                    btn.style.width = '250px';
                });
            }
        }

        // Check on load and resize
        window.addEventListener('load', checkMobile);
        window.addEventListener('resize', checkMobile);
    </script>
</body>
</html>

﻿@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="da">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Jeopardy Spil</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            min-height: 100vh;
            display: flex;
            justify-content: center;
            align-items: center;
            overflow-x: hidden;
        }

        /* Animated background circles */
        .bg-circle {
            position: absolute;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.05);
            animation: float 20s infinite ease-in-out;
        }

        .bg-circle:nth-child(1) {
            width: 300px;
            height: 300px;
            top: 10%;
            left: 10%;
            animation-delay: 0s;
        }

        .bg-circle:nth-child(2) {
            width: 200px;
            height: 200px;
            bottom: 15%;
            right: 15%;
            animation-delay: 5s;
        }

        .bg-circle:nth-child(3) {
            width: 150px;
            height: 150px;
            top: 60%;
            left: 70%;
            animation-delay: 10s;
        }

        @@keyframes float {
            0%, 100% { transform: translateY(0px) translateX(0px); }
            33% { transform: translateY(-30px) translateX(20px); }
            66% { transform: translateY(20px) translateX(-20px); }
        }

        .container {
            max-width: 900px;
            width: 95%;
            margin: 0 auto;
            padding: 20px;
            position: relative;
            z-index: 1;
        }

        .login-screen {
            text-align: center;
            animation: fadeIn 0.6s ease-out;
        }

        @@keyframes fadeIn {
            from {
                opacity: 0;
                transform: translateY(30px);
            }
            to {
                opacity: 1;
                transform: translateY(0);
            }
        }

        h1 {
            margin-bottom: 15px;
            font-size: 3.5em;
            font-weight: 700;
            text-shadow: 3px 3px 6px rgba(0, 0, 0, 0.3);
            letter-spacing: 2px;
        }

        .subtitle {
            font-size: 1.2em;
            margin-bottom: 40px;
            opacity: 0.9;
            font-weight: 300;
        }

        .input-group {
            margin: 30px 0;
            background: rgba(255, 255, 255, 0.15);
            padding: 30px;
            border-radius: 20px;
            backdrop-filter: blur(10px);
            box-shadow: 0 8px 32px rgba(0, 0, 0, 0.1);
        }

        .input-group input {
            width: 100%;
            padding: 18px 25px;
            border: 2px solid rgba(255, 255, 255, 0.3);
            border-radius: 12px;
            font-size: 1.1em;
            margin: 10px 0;
            background: rgba(255, 255, 255, 0.9);
            transition: all 0.3s ease;
        }

        .input-group input:focus {
            outline: none;
            border-color: #FFD700;
            transform: scale(1.02);
            box-shadow: 0 0 15px rgba(255, 215, 0, 0.3);
        }

        .mode-selection {
            margin: 30px 0;
        }

        .mode-selection h2 {
            font-size: 1.5em;
            margin-bottom: 25px;
            font-weight: 500;
        }

        .mode-cards {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 25px;
            margin-top: 20px;
        }

        .mode-card {
            background: rgba(255, 255, 255, 0.15);
            padding: 35px 25px;
            border-radius: 20px;
            cursor: pointer;
            transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
            backdrop-filter: blur(10px);
            border: 3px solid transparent;
            position: relative;
            overflow: hidden;
        }

        .mode-card::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(135deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0));
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .mode-card:hover {
            transform: translateY(-10px) scale(1.05);
            border-color: #FFD700;
            box-shadow: 0 15px 40px rgba(0, 0, 0, 0.3);
        }

        .mode-card:hover::before {
            opacity: 1;
        }

        .mode-card:active {
            transform: translateY(-5px) scale(1.02);
        }

        .mode-icon {
            font-size: 3.5em;
            margin-bottom: 15px;
            display: block;
            animation: bounce 2s infinite;
        }

        @@keyframes bounce {
            0%, 100% { transform: translateY(0); }
            50% { transform: translateY(-10px); }
        }

        .mode-title {
            font-size: 1.4em;
            font-weight: 600;
            margin-bottom: 10px;
        }

        .mode-description {
            font-size: 0.95em;
            opacity: 0.85;
            line-height: 1.5;
        }

        .join-section {
            margin-top: 40px;
            padding-top: 30px;
            border-top: 2px solid rgba(255, 255, 255, 0.2);
        }

        .btn {
            background: linear-gradient(135deg, #FFD700, #FFA500);
            border: none;
            color: #000;
            padding: 18px 40px;
            font-size: 1.2em;
            font-weight: 600;
            border-radius: 50px;
            cursor: pointer;
            transition: all 0.3s ease;
            margin: 10px;
            width: 100%;
            max-width: 300px;
            box-shadow: 0 5px 20px rgba(255, 215, 0, 0.4);
        }

        .btn:hover {
            transform: translateY(-3px);
            box-shadow: 0 8px 30px rgba(255, 215, 0, 0.6);
        }

        .btn:active {
            transform: translateY(-1px);
        }

        @@media (max-width: 768px) {
            h1 {
                font-size: 2.5em;
            }

            .mode-cards {
                grid-template-columns: 1fr;
            }

            .bg-circle {
                display: none;
            }
        }
    </style>
</head>
<body>
    <!-- Animated background -->
    <div class="bg-circle"></div>
    <div class="bg-circle"></div>
    <div class="bg-circle"></div>

    <div class="container">
        <div class="login-screen">
            <h1> Musikquiz</h1>
            <p class="subtitle">Vælg din spilletilstand og gå i gang!</p>

            <div class="input-group">
                <input type="text" id="playerName" placeholder="Indtast dit navn" maxlength="20">
            </div>

            <div class="mode-selection">
                <h2>Opret Spil som Vært</h2>
                <div class="mode-cards">
                    <div class="mode-card" onclick="createAsHost(false)">
                        <span class="mode-icon"></span>
                        <div class="mode-title">Solo Spil</div>
                        <div class="mode-description">Spil individuelt - hver spiller for sig selv</div>
                    </div>
                    <div class="mode-card" onclick="createAsHost(true)">
                        <span class="mode-icon"></span>
                        <div class="mode-title">Hold Spil</div>
                        <div class="mode-description">Spil i hold - samarbejd om at vinde</div>
                    </div>
                </div>
            </div>

            <div class="join-section">
                <h2>Eller tilslut til et eksisterende spil</h2>
                <div class="input-group">
                    <input type="text" id="gameCode" placeholder="Indtast spil kode">
                    <button class="btn" onclick="joinAsPlayer()">Tilslut som Spiller</button>
                </div>
            </div>
        </div>
    </div>

    <script>
        function joinAsPlayer() {
            const name = document.getElementById('playerName').value.trim();
            const code = document.getElementById('gameCode').value.trim();

            if (!name || !code) {
                alert('Indtast venligst navn og spil kode');
                return;
            }

            localStorage.setItem('playerName', name);
            localStorage.setItem('gameCode', code);
            window.location.href = '/Home/Play';
        }

        function createAsHost(isTeamMode) {
            const name = document.getElementById('playerName').value.trim();

            if (!name) {
                alert('Indtast venligst dit navn');
                return;
            }

            localStorage.setItem('hostName', name);
            localStorage.setItem('isTeamMode', isTeamMode ? 'true' : 'false');
            window.location.href = '/Home/Host';
        }

        // Make buttons responsive on mobile
        function checkMobile() {
            const buttons = document.querySelectorAll('.btn');
            if (window.innerWidth <= 768) {
                buttons.forEach(btn => {
                    btn.style.width = '100%';
                });
            } else {
                buttons.forEach(btn => {
                    btn.style.width = '250px';
                });
            }
        }

        // Check on load and resize
        window.addEventListener('load', checkMobile);
        window.addEventListener('resize', checkMobile);
    </script>
</body>
</html>

﻿@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="da">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no, maximum-scale=1.0">
    <title>Jeopardy - Spiller</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Arial', sans-serif;
            background: linear-gradient(135deg, #1e3c72, #2a5298);
            color: white;
            min-height: 100vh;
            padding: 10px;
            touch-action: manipulation;
        }

        .container {
            max-width: 1000px;
            margin: 0 auto;
        }

        .player-header {
            text-align: center;
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 15px;
            margin-bottom: 15px;
            backdrop-filter: blur(10px);
        }

        .game-board {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 8px;
            margin: 15px 0;
        }

        .category-header {
            background: #FFD700;
            color: #000;
            padding: 10px;
            text-align: center;
            font-weight: bold;
            font-size: 0.9em;
            border-radius: 8px;
            text-transform: uppercase;
        }

        .question-tile {
            background: #000080;
            color: #FFD700;
            padding: 15px;
            text-align: center;
            font-size: 1.2em;
            font-weight: bold;
            border-radius: 8px;
            border: 3px solid #FFD700;
            min-height: 60px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

            .question-tile.used {
                background: #333;
                color: #666;
                opacity: 0.5;
            }

        .buzz-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(45deg, #ff6b6b, #ee5a24);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            color: white;
            font-size: 3em;
            font-weight: bold;
            cursor: pointer;
            z-index: 1000;
            transition: all 0.3s ease;
            text-align: center;
            padding: 20px;
            touch-action: manipulation;
        }

            .buzz-overlay:hover {
                background: linear-gradient(45deg, #ff5252, #d84315);
                transform: scale(1.02);
            }

            .buzz-overlay:active {
                transform: scale(0.98);
            }

            .buzz-overlay.disabled {
                background: #666;
                cursor: not-allowed;
                transform: none;
            }

            .buzz-overlay .question-info {
                font-size: 0.4em;
                margin-bottom: 20px;
                opacity: 0.9;
            }

            .buzz-overlay .buzz-text {
                text-shadow: 3px 3px 6px rgba(0, 0, 0, 0.5);
                animation: pulse 2s infinite;
            }

        @@keyframes pulse {
            0% {
                transform: scale(1);
            }

            50% {
                transform: scale(1.05);
            }

            100% {
                transform: scale(1);
            }
        }

        .status {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            margin: 15px 0;
            text-align: center;
            backdrop-filter: blur(10px);
        }

        .players-list {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
            gap: 10px;
            margin: 15px 0;
        }

        .player-card {
            background: rgba(255, 255, 255, 0.1);
            padding: 10px;
            border-radius: 10px;
            text-align: center;
        }

        .player-score {
            font-size: 1.2em;
            color: #FFD700;
            font-weight: bold;
        }

        .btn {
            background: linear-gradient(45deg, #667eea, #764ba2);
            border: none;
            color: white;
            padding: 12px 25px;
            font-size: 1em;
            border-radius: 8px;
            cursor: pointer;
            margin: 10px;
            transition: all 0.3s ease;
            touch-action: manipulation;
        }

            .btn:hover {
                transform: translateY(-2px);
                box-shadow: 0 8px 15px rgba(0, 0, 0, 0.3);
            }

        .btn-danger {
            background: linear-gradient(45deg, #ff6b6b, #ee5a24);
        }

        .current-question {
            background: rgba(255, 215, 0, 0.2);
            padding: 15px;
            border-radius: 10px;
            margin: 15px 0;
            text-align: center;
            border: 2px solid #FFD700;
        }

        .hidden {
            display: none;
        }

        /* Team Mode Styles */
        .team-lobby {
            background: rgba(255, 255, 255, 0.1);
            padding: 20px;
            border-radius: 15px;
            margin: 15px 0;
            backdrop-filter: blur(10px);
        }

        .teams-list {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 15px;
            margin: 15px 0;
        }

        .team-card-selectable {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            border-left: 5px solid;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        .team-card-selectable:hover {
            background: rgba(255, 255, 255, 0.2);
            transform: translateY(-2px);
        }

        .team-card-selectable.selected {
            background: rgba(76, 175, 80, 0.3);
            box-shadow: 0 0 20px rgba(76, 175, 80, 0.5);
        }

        .team-members-count {
            font-size: 0.9em;
            margin-top: 5px;
            opacity: 0.8;
        }

        /* Mobile-first responsive design */
        @@media (max-width: 480px) {
            body {
                padding: 5px;
            }

            .game-board {
                grid-template-columns: repeat(2, 1fr);
                gap: 5px;
            }

            .category-header {
                padding: 8px 4px;
                font-size: 0.7em;
            }

            .question-tile {
                padding: 8px;
                font-size: 1em;
                min-height: 50px;
            }

            .buzz-overlay {
                font-size: 2.5em;
                padding: 15px;
            }

            .players-list {
                grid-template-columns: repeat(2, 1fr);
                gap: 8px;
            }

            .player-card {
                padding: 8px;
            }

            .player-score {
                font-size: 1.1em;
            }

            .player-header {
                padding: 10px;
                margin-bottom: 10px;
            }

            .player-header h1 {
                font-size: 1.5em;
            }

            .player-header h2 {
                font-size: 1.2em;
            }

            .status {
                padding: 10px;
                margin: 10px 0;
                font-size: 0.9em;
            }

            .current-question {
                padding: 10px;
                margin: 10px 0;
            }

            .btn {
                padding: 10px 20px;
                font-size: 0.9em;
                margin: 5px;
            }
        }

        @@media (max-width: 768px) and (min-width: 481px) {
            .game-board {
                grid-template-columns: repeat(3, 1fr);
                gap: 6px;
            }

            .question-tile {
                padding: 12px;
                font-size: 1.1em;
                min-height: 55px;
            }

            .buzz-overlay {
                font-size: 2.8em;
            }

            .players-list {
                grid-template-columns: repeat(3, 1fr);
            }
        }

        /* Landscape orientation adjustments for mobile */
        @@media (max-width: 896px) and (orientation: landscape) {
            .game-board {
                grid-template-columns: repeat(5, 1fr);
                gap: 4px;
            }

            .question-tile {
                padding: 8px 4px;
                font-size: 0.9em;
                min-height: 45px;
            }

            .category-header {
                padding: 6px 2px;
                font-size: 0.6em;
            }

            .buzz-overlay {
                font-size: 2.2em;
            }

            .players-list {
                grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="player-header">
            <h1> Jeopardy</h1>
            <h2>Spiller: <span id="playerName">-</span></h2>
            <div class="status">
                <div id="gameStatus">Venter på forbindelse...</div>
            </div>
        </div>

        <!-- Team Lobby (shown only in team mode before game starts) -->
        <div id="teamLobby" class="team-lobby hidden">
            <h2>Vælg dit hold</h2>
            <div class="status">
                Venter på at værten starter spillet...
            </div>
            <div id="teamsList" class="teams-list"></div>
        </div>

        <div class="players-list" id="playersList"></div>

        <div id="gameBoard" class="game-board"></div>

        <div id="currentQuestion" class="current-question hidden">
            <h2>Aktuelt spørgsmål</h2>
            <div id="questionValue">-</div>
        </div>

        <div id="buzzOverlay" class="buzz-overlay hidden" onclick="buzz()">
            <div class="question-info" id="overlayQuestionInfo">Spørgsmål valgt</div>
            <div class="buzz-text"> TRYK FOR AT BUZZE! </div>
        </div>

        <div class="player-header">
            <button class="btn btn-danger" onclick="leaveGame()">Forlad Spil</button>
        </div>
    </div>

    <script src="https://cdnjs.cloudflare.com/ajax/libs/microsoft-signalr/6.0.1/signalr.min.js"></script>
    <script>
        const connection = new signalR.HubConnectionBuilder()
            .withUrl("/gameHub")
            .build();

        let gameData = {
            gameCode: '',
            playerId: '',
            playerName: '',
            teamId: null,
            board: null,
            players: {},
            teams: {},
            isTeamMode: false,
            isGameStarted: false,
            currentQuestionValue: 0
        };

        // Start connection
        connection.start().then(function () {
            const playerName = localStorage.getItem('playerName');
            const gameCode = localStorage.getItem('gameCode');

            if (!playerName || !gameCode) {
                alert('Manglende spiller information');
                window.location.href = '/';
                return;
            }

            gameData.playerName = playerName;
            gameData.gameCode = gameCode;
            document.getElementById('playerName').textContent = playerName;

            connection.invoke("JoinGame", gameCode, playerName);
        }).catch(function (err) {
            console.error('Connection error:', err);
            alert('Kunne ikke oprette forbindelse til serveren');
        });

        // Event handlers
        connection.on("JoinedGame", function (data) {
            gameData.gameCode = data.gameCode;
            gameData.playerId = data.playerId;
            gameData.playerName = data.playerName;
            gameData.board = data.board;
            gameData.isTeamMode = data.isTeamMode;
            gameData.isGameStarted = data.isGameStarted;

            if (data.teams) {
                gameData.teams = {};
                data.teams.forEach(t => gameData.teams[t.id] = t);
            }

            if (gameData.isTeamMode && !gameData.isGameStarted) {
                // Show team lobby
                document.getElementById('teamLobby').classList.remove('hidden');
                document.getElementById('gameBoard').classList.add('hidden');
                document.getElementById('gameStatus').textContent = `Tilsluttet spil: ${data.gameCode} - Vælg dit hold`;
                updateTeamsDisplay();
            } else {
                // Show game board
                document.getElementById('teamLobby').classList.add('hidden');
                document.getElementById('gameStatus').textContent = `Tilsluttet spil: ${data.gameCode}`;
                renderBoard();
            }
        });

        connection.on("Error", function (message) {
            alert(message);
            window.location.href = '/';
        });

        connection.on("PlayersUpdated", function (players) {
            gameData.players = {};
            players.forEach(p => gameData.players[p.id] = p);

            if (gameData.isTeamMode && gameData.isGameStarted) {
                updateTeamPlayersDisplay();
            } else if (!gameData.isTeamMode) {
                updatePlayersDisplay();
            }
        });

        connection.on("QuestionSelected", function (data) {
            gameData.board = data.board;
            gameData.currentQuestionValue = data.value;
            renderBoard();
            showQuestion(data.value);
            document.getElementById('gameStatus').textContent = `Spørgsmål valgt: ${data.value} point`;
        });

        connection.on("BuzzingStarted", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            const overlayInfo = document.getElementById('overlayQuestionInfo');

            buzzOverlay.classList.remove('hidden', 'disabled');
            overlayInfo.textContent = `Spørgsmål: ${gameData.currentQuestionValue} point`;

            // Don't set automatic timeout - players can buzz indefinitely until someone actually buzzes
        });

        connection.on("BuzzDisabled", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            buzzOverlay.classList.add('disabled');
            document.querySelector('.buzz-text').textContent = '✅ Du har buzzet!';
        });

        // Add new event handler for when buzz timer starts (after first player buzzes)
        connection.on("BuzzTimerStarted", function () {
            // Start 10 second countdown for other players to buzz, but don't disable after 10 seconds
            // The extended timer will handle final disabling
            setTimeout(() => {
                const buzzOverlay = document.getElementById('buzzOverlay');
                if (!buzzOverlay.classList.contains('hidden') && !buzzOverlay.classList.contains('disabled')) {
                    // Don't disable here - just change text to indicate extended time
                    document.querySelector('.buzz-text').textContent = '⏰ Extra tid!';
                }
            }, 10000);
        });

        connection.on("BuzzReset", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            buzzOverlay.classList.add('hidden');
            buzzOverlay.classList.remove('disabled');
            document.querySelector('.buzz-text').textContent = ' TRYK FOR AT BUZZE! ';
            document.getElementById('currentQuestion').classList.add('hidden');
            document.getElementById('gameStatus').textContent = 'Klar til næste spørgsmål';
        });

        // Add new event handler for when host returns to board
        connection.on("HostReturnedToBoard", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            buzzOverlay.classList.add('hidden');
            buzzOverlay.classList.remove('disabled');
            document.querySelector('.buzz-text').textContent = ' TRYK FOR AT BUZZE! ';
            document.getElementById('currentQuestion').classList.add('hidden');
            document.getElementById('gameStatus').textContent = 'Venter på næste spørgsmål';
        });

        connection.on("ScoreUpdated", function (data) {
            if (gameData.isTeamMode && data.teams) {
                // Update teams and players
                gameData.teams = {};
                data.teams.forEach(t => gameData.teams[t.id] = t);
                gameData.players = {};
                data.players.forEach(p => gameData.players[p.id] = p);
                updateTeamPlayersDisplay();
            } else if (gameData.players[data.playerId]) {
                gameData.players[data.playerId].score = data.newScore;
                updatePlayersDisplay();
            }
        });

        connection.on("GameEnded", function (reason) {
            alert(`Spillet er afsluttet: ${reason}`);
            window.location.href = '/';
        });

        function renderBoard() {
            const board = document.getElementById('gameBoard');
            board.innerHTML = '';

            // Add category headers
            gameData.board.categories.forEach(category => {
                const header = document.createElement('div');
                header.className = 'category-header';
                header.textContent = category.name;
                board.appendChild(header);
            });

            // Add question tiles
            for (let i = 0; i < 5; i++) {
                gameData.board.categories.forEach((category, catIndex) => {
                    const tile = document.createElement('div');
                    const question = category.questions[i];
                    tile.className = `question-tile ${question.isUsed ? 'used' : ''}`;
                    tile.textContent = question.value;
                    board.appendChild(tile);
                });
            }
        }

        function updatePlayersDisplay() {
            const playersList = document.getElementById('playersList');
            const players = Object.values(gameData.players);

            playersList.innerHTML = '';
            players.forEach(player => {
                const card = document.createElement('div');
                card.className = 'player-card';
                card.innerHTML = `
                    <h4>${player.name}</h4>
                    <div class="player-score">${player.score}</div>
                `;
                playersList.appendChild(card);
            });
        }

        function showQuestion(value) {
            const questionDiv = document.getElementById('currentQuestion');
            const valueDiv = document.getElementById('questionValue');
            valueDiv.textContent = `${value} point`;
            questionDiv.classList.remove('hidden');
        }

        function buzz() {
            const buzzOverlay = document.getElementById('buzzOverlay');
            if (buzzOverlay.classList.contains('disabled') || buzzOverlay.classList.contains('hidden')) {
                return;
            }
            connection.invoke("Buzz");
        }

        function leaveGame() {
            if (confirm('Er du sikker på, at du vil forlade spillet?')) {
                window.location.href = '/';
            }
        }

        // Handle connection loss
        connection.onclose(function () {
            alert('Forbindelse til serveren blev afbrudt');
            window.location.href = '/';
        });

        // Team mode event handlers
        connection.on("TeamCreated", function (data) {
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            if (gameData.isTeamMode && !gameData.isGameStarted) {
                updateTeamsDisplay();
            }
        });

        connection.on("TeamsUpdated", function (data) {
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            gameData.players = {};
            data.players.forEach(p => gameData.players[p.id] = p);

            // Update our team ID if we're in a team
            const ourPlayer = Object.values(gameData.players).find(p => p.id === gameData.playerId);
            if (ourPlayer) {
                gameData.teamId = ourPlayer.teamId;
            }

            if (gameData.isTeamMode && !gameData.isGameStarted) {
                updateTeamsDisplay();
            }
        });

        connection.on("GameStarted", function (data) {
            gameData.isGameStarted = true;
            gameData.board = data.board;
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            gameData.players = {};
            data.players.forEach(p => gameData.players[p.id] = p);

            // Hide team lobby, show game board
            document.getElementById('teamLobby').classList.add('hidden');
            document.getElementById('gameBoard').classList.remove('hidden');
            document.getElementById('gameStatus').textContent = 'Spillet er startet!';

            renderBoard();
            updateTeamPlayersDisplay();
        });

        function updateTeamsDisplay() {
            const teamsList = document.getElementById('teamsList');
            teamsList.innerHTML = '';

            if (Object.keys(gameData.teams).length === 0) {
                teamsList.innerHTML = '<div style="text-align: center; padding: 20px;">Værten har ikke oprettet nogen hold endnu...</div>';
                return;
            }

            Object.values(gameData.teams).forEach(team => {
                const teamCard = document.createElement('div');
                teamCard.className = 'team-card-selectable';
                teamCard.style.borderLeftColor = team.color;

                if (gameData.teamId === team.id) {
                    teamCard.classList.add('selected');
                }

                const memberCount = team.playerIds ? team.playerIds.length : 0;

                teamCard.innerHTML = `
                    <h3 style="color: ${team.color}">${team.name}</h3>
                    <div class="team-members-count">${memberCount} medlem${memberCount !== 1 ? 'mer' : ''}</div>
                `;

                teamCard.onclick = () => selectTeam(team.id);
                teamsList.appendChild(teamCard);
            });
        }

        function selectTeam(teamId) {
            connection.invoke("JoinTeam", teamId);
        }

        function updateTeamPlayersDisplay() {
            const playersList = document.getElementById('playersList');
            playersList.innerHTML = '';

            Object.values(gameData.teams).forEach(team => {
                const teamPlayers = Object.values(gameData.players).filter(p => p.teamId === team.id);
                if (teamPlayers.length === 0) return;

                const card = document.createElement('div');
                card.className = 'player-card';
                card.style.borderLeft = `5px solid ${team.color}`;

                const playerNames = teamPlayers.map(p => p.name).join(', ');

                card.innerHTML = `
                    <h4 style="color: ${team.color}">${team.name}</h4>
                    <div style="font-size: 0.8em; margin: 3px 0;">${playerNames}</div>
                    <div class="player-score">${team.score}</div>
                `;
                playersList.appendChild(card);
            });
        }

        // Prevent zoom on double-tap on iOS
        let lastTouchEnd = 0;
        document.addEventListener('touchend', function (event) {
            const now = (new Date()).getTime();
            if (now - lastTouchEnd <= 300) {
                event.preventDefault();
            }
            lastTouchEnd = now;
        }, false);

        connection.on("BuzzTimeExpired", function () {
            // Don't disable buzz overlay yet - extended timer starts
            const buzzOverlay = document.getElementById('buzzOverlay');
            if (!buzzOverlay.classList.contains('hidden') && !buzzOverlay.classList.contains('disabled')) {
                document.querySelector('.buzz-text').textContent = '⏰ Extra tid!';
            }
        });

        // Add new event handler for extended timer expiration
        connection.on("ExtendedBuzzTimeExpired", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            if (!buzzOverlay.classList.contains('hidden') && !buzzOverlay.classList.contains('disabled')) {
                buzzOverlay.classList.add('disabled');
                document.querySelector('.buzz-text').textContent = '⏰ Alle tider udløbet!';
            }
        });
    </script>
</body>
</html>

﻿@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="da">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no, maximum-scale=1.0">
    <title>Jeopardy - Spiller</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Arial', sans-serif;
            background: linear-gradient(135deg, #1e3c72, #2a5298);
            color: white;
            min-height: 100vh;
            padding: 10px;
            touch-action: manipulation;
        }

        .container {
            max-width: 1000px;
            margin: 0 auto;
        }

        .player-header {
            text-align: center;
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 15px;
            margin-bottom: 15px;
            backdrop-filter: blur(10px);
        }

        .game-board {
            display: grid;
            grid-template-columns: repeat(5, 1fr);
            gap: 8px;
            margin: 15px 0;
        }

        .category-header {
            background: #FFD700;
            color: #000;
            padding: 10px;
            text-align: center;
            font-weight: bold;
            font-size: 0.9em;
            border-radius: 8px;
            text-transform: uppercase;
        }

        .question-tile {
            background: #000080;
            color: #FFD700;
            padding: 15px;
            text-align: center;
            font-size: 1.2em;
            font-weight: bold;
            border-radius: 8px;
            border: 3px solid #FFD700;
            min-height: 60px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

            .question-tile.used {
                background: #333;
                color: #666;
                opacity: 0.5;
            }

        .buzz-overlay {
            position: fixed;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(45deg, #ff6b6b, #ee5a24);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            color: white;
            font-size: 3em;
            font-weight: bold;
            cursor: pointer;
            z-index: 1000;
            transition: all 0.3s ease;
            text-align: center;
            padding: 20px;
            touch-action: manipulation;
        }

            .buzz-overlay:hover {
                background: linear-gradient(45deg, #ff5252, #d84315);
                transform: scale(1.02);
            }

            .buzz-overlay:active {
                transform: scale(0.98);
            }

            .buzz-overlay.disabled {
                background: #666;
                cursor: not-allowed;
                transform: none;
            }

            .buzz-overlay .question-info {
                font-size: 0.4em;
                margin-bottom: 20px;
                opacity: 0.9;
            }

            .buzz-overlay .buzz-text {
                text-shadow: 3px 3px 6px rgba(0, 0, 0, 0.5);
                animation: pulse 2s infinite;
            }

        @@keyframes pulse {
            0% {
                transform: scale(1);
            }

            50% {
                transform: scale(1.05);
            }

            100% {
                transform: scale(1);
            }
        }

        .status {
            background: rgba(255, 255, 255, 0.1);
            padding: 15px;
            border-radius: 10px;
            margin: 15px 0;
            text-align: center;
            backdrop-filter: blur(10px);
        }

        .players-list {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
            gap: 10px;
            margin: 15px 0;
        }

        .player-card {
            background: rgba(255, 255, 255, 0.1);
            padding: 10px;
            border-radius: 10px;
            text-align: center;
        }

        .player-score {
            font-size: 1.2em;
            color: #FFD700;
            font-weight: bold;
        }

        .btn {
            background: linear-gradient(45deg, #667eea, #764ba2);
            border: none;
            color: white;
            padding: 12px 25px;
            font-size: 1em;
            border-radius: 8px;
            cursor: pointer;
            margin: 10px;
            transition: all 0.3s ease;
            touch-action: manipulation;
        }

            .btn:hover {
                transform: translateY(-2px);
                box-shadow: 0 8px 15px rgba(0, 0, 0, 0.3);
            }

        .btn-danger {
            background: linear-gradient(45deg, #ff6b6b, #ee5a24);
        }

        .current-question {
            background: rgba(255, 215, 0, 0.2);
            padding: 15px;
            border-radius: 10px;
            margin: 15px 0;
            text-align: center;
            border: 2px solid #FFD700;
        }

        .hidden {
            display: none;
        }

        /* Team Mode Styles - Modern Design */
        .team-lobby {
            background: linear-gradient(135deg, rgba(102, 126, 234, 0.2), rgba(118, 75, 162, 0.2));
            padding: 25px;
            border-radius: 20px;
            margin: 15px 0;
            backdrop-filter: blur(15px);
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
            border: 2px solid rgba(255, 255, 255, 0.2);
        }

        .team-lobby h2 {
            font-size: 1.8em;
            margin-bottom: 15px;
            text-align: center;
            text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
        }

        .team-lobby .status {
            background: rgba(255, 215, 0, 0.2);
            padding: 12px;
            border-radius: 10px;
            margin-bottom: 20px;
            border: 2px solid rgba(255, 215, 0, 0.4);
            font-weight: 500;
        }

        .teams-list {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 20px;
            margin: 20px 0;
        }

        .team-card-selectable {
            background: rgba(255, 255, 255, 0.15);
            padding: 25px 20px;
            border-radius: 15px;
            border-left: 6px solid;
            cursor: pointer;
            transition: all 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
            position: relative;
            overflow: hidden;
        }

        .team-card-selectable::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background: linear-gradient(135deg, rgba(255, 255, 255, 0.1), rgba(255, 255, 255, 0));
            opacity: 0;
            transition: opacity 0.3s ease;
        }

        .team-card-selectable:hover {
            background: rgba(255, 255, 255, 0.25);
            transform: translateY(-8px) scale(1.05);
            box-shadow: 0 15px 35px rgba(0, 0, 0, 0.4);
        }

        .team-card-selectable:hover::before {
            opacity: 1;
        }

        .team-card-selectable.selected {
            background: rgba(76, 175, 80, 0.4);
            border-left-width: 8px;
            border-color: #4CAF50;
            box-shadow: 0 10px 40px rgba(76, 175, 80, 0.6);
            transform: scale(1.05);
        }

        .team-card-selectable.selected::after {
            content: '✓';
            position: absolute;
            top: 10px;
            right: 10px;
            width: 35px;
            height: 35px;
            background: #4CAF50;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 1.5em;
            font-weight: bold;
            color: white;
        }

        .team-card-selectable h3 {
            font-size: 1.4em;
            margin-bottom: 10px;
            position: relative;
            z-index: 1;
        }

        .team-members-count {
            font-size: 0.95em;
            margin-top: 8px;
            opacity: 0.9;
            display: flex;
            align-items: center;
            gap: 6px;
            position: relative;
            z-index: 1;
        }

        .team-members-count::before {
            content: '';
            font-size: 1.2em;
        }

        /* Mobile-first responsive design */
        @@media (max-width: 480px) {
            body {
                padding: 5px;
            }

            .game-board {
                grid-template-columns: repeat(2, 1fr);
                gap: 5px;
            }

            .category-header {
                padding: 8px 4px;
                font-size: 0.7em;
            }

            .question-tile {
                padding: 8px;
                font-size: 1em;
                min-height: 50px;
            }

            .buzz-overlay {
                font-size: 2.5em;
                padding: 15px;
            }

            .players-list {
                grid-template-columns: repeat(2, 1fr);
                gap: 8px;
            }

            .player-card {
                padding: 8px;
            }

            .player-score {
                font-size: 1.1em;
            }

            .player-header {
                padding: 10px;
                margin-bottom: 10px;
            }

            .player-header h1 {
                font-size: 1.5em;
            }

            .player-header h2 {
                font-size: 1.2em;
            }

            .status {
                padding: 10px;
                margin: 10px 0;
                font-size: 0.9em;
            }

            .current-question {
                padding: 10px;
                margin: 10px 0;
            }

            .btn {
                padding: 10px 20px;
                font-size: 0.9em;
                margin: 5px;
            }
        }

        @@media (max-width: 768px) and (min-width: 481px) {
            .game-board {
                grid-template-columns: repeat(3, 1fr);
                gap: 6px;
            }

            .question-tile {
                padding: 12px;
                font-size: 1.1em;
                min-height: 55px;
            }

            .buzz-overlay {
                font-size: 2.8em;
            }

            .players-list {
                grid-template-columns: repeat(3, 1fr);
            }
        }

        /* Landscape orientation adjustments for mobile */
        @@media (max-width: 896px) and (orientation: landscape) {
            .game-board {
                grid-template-columns: repeat(5, 1fr);
                gap: 4px;
            }

            .question-tile {
                padding: 8px 4px;
                font-size: 0.9em;
                min-height: 45px;
            }

            .category-header {
                padding: 6px 2px;
                font-size: 0.6em;
            }

            .buzz-overlay {
                font-size: 2.2em;
            }

            .players-list {
                grid-template-columns: repeat(auto-fit, minmax(100px, 1fr));
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="player-header">
            <h1> Jeopardy</h1>
            <h2>Spiller: <span id="playerName">-</span></h2>
            <div class="status">
                <div id="gameStatus">Venter på forbindelse...</div>
            </div>
        </div>

        <!-- Team Lobby (shown only in team mode before game starts) -->
        <div id="teamLobby" class="team-lobby hidden">
            <h2>Vælg dit hold</h2>
            <div class="status">
                Venter på at værten starter spillet...
            </div>
            <div id="teamsList" class="teams-list"></div>
        </div>

        <div class="players-list" id="playersList"></div>

        <div id="gameBoard" class="game-board"></div>

        <div id="currentQuestion" class="current-question hidden">
            <h2>Aktuelt spørgsmål</h2>
            <div id="questionValue">-</div>
        </div>

        <div id="buzzOverlay" class="buzz-overlay hidden" onclick="buzz()">
            <div class="question-info" id="overlayQuestionInfo">Spørgsmål valgt</div>
            <div class="buzz-text"> TRYK FOR AT BUZZE! </div>
        </div>

        <div class="player-header">
            <button class="btn btn-danger" onclick="leaveGame()">Forlad Spil</button>
        </div>
    </div>

    <script src="https://cdnjs.cloudflare.com/ajax/libs/microsoft-signalr/6.0.1/signalr.min.js"></script>
    <script>
        const connection = new signalR.HubConnectionBuilder()
            .withUrl("/gameHub")
            .build();

        let gameData = {
            gameCode: '',
            playerId: '',
            playerName: '',
            teamId: null,
            board: null,
            players: {},
            teams: {},
            isTeamMode: false,
            isGameStarted: false,
            currentQuestionValue: 0
        };

        // Start connection
        connection.start().then(function () {
            const playerName = localStorage.getItem('playerName');
            const gameCode = localStorage.getItem('gameCode');

            if (!playerName || !gameCode) {
                alert('Manglende spiller information');
                window.location.href = '/';
                return;
            }

            gameData.playerName = playerName;
            gameData.gameCode = gameCode;
            document.getElementById('playerName').textContent = playerName;

            connection.invoke("JoinGame", gameCode, playerName);
        }).catch(function (err) {
            console.error('Connection error:', err);
            alert('Kunne ikke oprette forbindelse til serveren');
        });

        // Event handlers
        connection.on("JoinedGame", function (data) {
            gameData.gameCode = data.gameCode;
            gameData.playerId = data.playerId;
            gameData.playerName = data.playerName;
            gameData.board = data.board;
            gameData.isTeamMode = data.isTeamMode;
            gameData.isGameStarted = data.isGameStarted;

            if (data.teams) {
                gameData.teams = {};
                data.teams.forEach(t => gameData.teams[t.id] = t);
            }

            if (gameData.isTeamMode && !gameData.isGameStarted) {
                // Show team lobby
                document.getElementById('teamLobby').classList.remove('hidden');
                document.getElementById('gameBoard').classList.add('hidden');
                document.getElementById('gameStatus').textContent = `Tilsluttet spil: ${data.gameCode} - Vælg dit hold`;
                updateTeamsDisplay();
            } else {
                // Show game board
                document.getElementById('teamLobby').classList.add('hidden');
                document.getElementById('gameStatus').textContent = `Tilsluttet spil: ${data.gameCode}`;
                renderBoard();
            }
        });

        connection.on("Error", function (message) {
            alert(message);
            window.location.href = '/';
        });

        connection.on("PlayersUpdated", function (players) {
            gameData.players = {};
            players.forEach(p => gameData.players[p.id] = p);

            if (gameData.isTeamMode && gameData.isGameStarted) {
                updateTeamPlayersDisplay();
            } else if (!gameData.isTeamMode) {
                updatePlayersDisplay();
            }
        });

        connection.on("QuestionSelected", function (data) {
            gameData.board = data.board;
            gameData.currentQuestionValue = data.value;
            renderBoard();
            showQuestion(data.value);
            document.getElementById('gameStatus').textContent = `Spørgsmål valgt: ${data.value} point`;
        });

        connection.on("BuzzingStarted", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            const overlayInfo = document.getElementById('overlayQuestionInfo');

            buzzOverlay.classList.remove('hidden', 'disabled');
            overlayInfo.textContent = `Spørgsmål: ${gameData.currentQuestionValue} point`;

            // Don't set automatic timeout - players can buzz indefinitely until someone actually buzzes
        });

        connection.on("BuzzDisabled", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            buzzOverlay.classList.add('disabled');
            document.querySelector('.buzz-text').textContent = '✅ Du har buzzet!';
        });

        connection.on("TeamAnswering", function (data) {
            // Another team is answering - lock our buzz button
            const buzzOverlay = document.getElementById('buzzOverlay');
            if (!buzzOverlay.classList.contains('disabled')) {
                buzzOverlay.classList.add('disabled');
                document.querySelector('.buzz-text').textContent = `⏳ ${data.teamName} svarer...`;
            }
        });

        connection.on("TeamAnswerTimeUp", function () {
            // Other team's time is up - enable buzz again if we haven't buzzed
            const buzzOverlay = document.getElementById('buzzOverlay');
            const player = gameData.players[gameData.playerId];

            // Only enable if we haven't buzzed yet
            if (player && (!gameData.isTeamMode || !player.teamId || 
                !gameData.teams[player.teamId] || 
                gameData.teams[player.teamId].playerIds.some(pid => {
                    const p = gameData.players[pid];
                    return p && p.id === gameData.playerId;
                }))) {
                buzzOverlay.classList.remove('disabled');
                document.querySelector('.buzz-text').textContent = ' TRYK FOR AT BUZZE! ';
            }
        });

        // Add new event handler for when buzz timer starts (after first player buzzes)
        connection.on("BuzzTimerStarted", function (data) {
            // Timer info is shown on host side only, players just keep their buzz overlay active
            // No need to show timer information to players
        });

        connection.on("BuzzReset", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            buzzOverlay.classList.add('hidden');
            buzzOverlay.classList.remove('disabled');
            document.querySelector('.buzz-text').textContent = ' TRYK FOR AT BUZZE! ';
            document.getElementById('currentQuestion').classList.add('hidden');
            document.getElementById('gameStatus').textContent = 'Klar til næste spørgsmål';
        });

        // Add new event handler for when host returns to board
        connection.on("HostReturnedToBoard", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            buzzOverlay.classList.add('hidden');
            buzzOverlay.classList.remove('disabled');
            document.querySelector('.buzz-text').textContent = ' TRYK FOR AT BUZZE! ';
            document.getElementById('currentQuestion').classList.add('hidden');
            document.getElementById('gameStatus').textContent = 'Venter på næste spørgsmål';
        });

        connection.on("ScoreUpdated", function (data) {
            if (gameData.isTeamMode && data.teams) {
                // Update teams and players
                gameData.teams = {};
                data.teams.forEach(t => gameData.teams[t.id] = t);
                gameData.players = {};
                data.players.forEach(p => gameData.players[p.id] = p);
                updateTeamPlayersDisplay();
            } else if (gameData.players[data.playerId]) {
                gameData.players[data.playerId].score = data.newScore;
                updatePlayersDisplay();
            }
        });

        connection.on("GameEnded", function (reason) {
            alert(`Spillet er afsluttet: ${reason}`);
            window.location.href = '/';
        });

        function renderBoard() {
            const board = document.getElementById('gameBoard');
            board.innerHTML = '';

            // Add category headers
            gameData.board.categories.forEach(category => {
                const header = document.createElement('div');
                header.className = 'category-header';
                header.textContent = category.name;
                board.appendChild(header);
            });

            // Add question tiles
            for (let i = 0; i < 5; i++) {
                gameData.board.categories.forEach((category, catIndex) => {
                    const tile = document.createElement('div');
                    const question = category.questions[i];
                    tile.className = `question-tile ${question.isUsed ? 'used' : ''}`;
                    tile.textContent = question.value;
                    board.appendChild(tile);
                });
            }
        }

        function updatePlayersDisplay() {
            const playersList = document.getElementById('playersList');
            const players = Object.values(gameData.players);

            playersList.innerHTML = '';
            players.forEach(player => {
                const card = document.createElement('div');
                card.className = 'player-card';
                card.innerHTML = `
                    <h4>${player.name}</h4>
                    <div class="player-score">${player.score}</div>
                `;
                playersList.appendChild(card);
            });
        }

        function showQuestion(value) {
            const questionDiv = document.getElementById('currentQuestion');
            const valueDiv = document.getElementById('questionValue');
            valueDiv.textContent = `${value} point`;
            questionDiv.classList.remove('hidden');
        }

        function buzz() {
            const buzzOverlay = document.getElementById('buzzOverlay');
            if (buzzOverlay.classList.contains('disabled') || buzzOverlay.classList.contains('hidden')) {
                return;
            }
            connection.invoke("Buzz");
        }

        function leaveGame() {
            if (confirm('Er du sikker på, at du vil forlade spillet?')) {
                window.location.href = '/';
            }
        }

        // Handle connection loss
        connection.onclose(function () {
            alert('Forbindelse til serveren blev afbrudt');
            window.location.href = '/';
        });

        // Team mode event handlers
        connection.on("TeamCreated", function (data) {
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            if (gameData.isTeamMode && !gameData.isGameStarted) {
                updateTeamsDisplay();
            }
        });

        connection.on("TeamsUpdated", function (data) {
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            gameData.players = {};
            data.players.forEach(p => gameData.players[p.id] = p);

            // Update our team ID if we're in a team
            const ourPlayer = Object.values(gameData.players).find(p => p.id === gameData.playerId);
            if (ourPlayer) {
                gameData.teamId = ourPlayer.teamId;
            }

            if (gameData.isTeamMode && !gameData.isGameStarted) {
                updateTeamsDisplay();
            }
        });

        connection.on("GameStarted", function (data) {
            gameData.isGameStarted = true;
            gameData.board = data.board;
            gameData.teams = {};
            data.teams.forEach(t => gameData.teams[t.id] = t);
            gameData.players = {};
            data.players.forEach(p => gameData.players[p.id] = p);

            // Hide team lobby, show game board
            document.getElementById('teamLobby').classList.add('hidden');
            document.getElementById('gameBoard').classList.remove('hidden');
            document.getElementById('gameStatus').textContent = 'Spillet er startet!';

            renderBoard();
            updateTeamPlayersDisplay();
        });

        function updateTeamsDisplay() {
            const teamsList = document.getElementById('teamsList');
            teamsList.innerHTML = '';

            if (Object.keys(gameData.teams).length === 0) {
                teamsList.innerHTML = '<div style="text-align: center; padding: 20px;">Værten har ikke oprettet nogen hold endnu...</div>';
                return;
            }

            Object.values(gameData.teams).forEach(team => {
                const teamCard = document.createElement('div');
                teamCard.className = 'team-card-selectable';
                teamCard.style.borderLeftColor = team.color;

                if (gameData.teamId === team.id) {
                    teamCard.classList.add('selected');
                }

                const memberCount = team.playerIds ? team.playerIds.length : 0;

                teamCard.innerHTML = `
                    <h3 style="color: ${team.color}">${team.name}</h3>
                    <div class="team-members-count">${memberCount} medlem${memberCount !== 1 ? 'mer' : ''}</div>
                `;

                teamCard.onclick = () => selectTeam(team.id);
                teamsList.appendChild(teamCard);
            });
        }

        function selectTeam(teamId) {
            connection.invoke("JoinTeam", teamId);
        }

        function updateTeamPlayersDisplay() {
            const playersList = document.getElementById('playersList');
            playersList.innerHTML = '';

            Object.values(gameData.teams).forEach(team => {
                const teamPlayers = Object.values(gameData.players).filter(p => p.teamId === team.id);
                if (teamPlayers.length === 0) return;

                const card = document.createElement('div');
                card.className = 'player-card';
                card.style.borderLeft = `5px solid ${team.color}`;

                const playerNames = teamPlayers.map(p => p.name).join(', ');

                card.innerHTML = `
                    <h4 style="color: ${team.color}">${team.name}</h4>
                    <div style="font-size: 0.8em; margin: 3px 0;">${playerNames}</div>
                    <div class="player-score">${team.score}</div>
                `;
                playersList.appendChild(card);
            });
        }

        // Prevent zoom on double-tap on iOS
        let lastTouchEnd = 0;
        document.addEventListener('touchend', function (event) {
            const now = (new Date()).getTime();
            if (now - lastTouchEnd <= 300) {
                event.preventDefault();
            }
            lastTouchEnd = now;
        }, false);

        connection.on("BuzzTimeExpired", function () {
            // Don't disable buzz overlay yet - extended timer starts
            // Timer info is shown on host side only
        });

        connection.on("BuzzExtraTimeStarted", function (data) {
            // Extra time started - timer info shown on host side only
            // Players just keep the buzz button active
        });

        // Add new event handler for extended timer expiration
        connection.on("ExtendedBuzzTimeExpired", function () {
            const buzzOverlay = document.getElementById('buzzOverlay');
            if (!buzzOverlay.classList.contains('hidden') && !buzzOverlay.classList.contains('disabled')) {
                buzzOverlay.classList.add('disabled');
                document.querySelector('.buzz-text').textContent = '⏰ Tiden er udløbet!';
            }
        });
    </script>
</body>
</html>
